L2_1 = {}
L2_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@2#Talk"
L2_1.m_CutScenProcessKey = 2
L2_1.m_CutScenID = 1700001
L2_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_LAUGH"
L2_1.m_CharStrID = "SOYEONG_POLICE_NULL_NULL"
L2_1.m_Pos = "C"
L2_1.m_Talk_KOREA = "어서 오세요, 경정님. 오늘도 일찍 나오셨네요."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "おはようございます、警視様。今日も早いですね。"
L2_1.m_Talk_ENG = "Good morning, Major. You're early as usual."
L2_1.m_Talk_TWN = "歡迎，警正大人，今天也好早啊。"
L2_1.m_Talk_THA = "อรุณสวัสดิ์ค่ะสารวัตร มาเช้าประจำเลยนะคะ"
L2_1.m_Talk_VTN = "Chào buổi sáng, Thiếu Tá. Cô vẫn tới sớm như thường lệ."
L2_1.m_Talk_SCN = "欢迎，警长大人，今天也好早啊。"
L2_1.m_Talk_DEU = "Guten Morgen, Major. Früh dran wie immer, was?"
L2_1.m_Talk_FRA = "Bonjour, major. Vous êtes matinale comme d'habitude."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 1700001
L3_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_HATE"
L3_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "경찰이라면 당연히 시간을 준수해야지."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "警察官たる者、時間は厳守しないと。"
L3_1.m_Talk_ENG = "I'm a police officer: I must be punctual."
L3_1.m_Talk_TWN = "警察當然要守時了。"
L3_1.m_Talk_THA = "ฉันเป็นเจ้าหน้าที่ตำรวจนะ ก็ต้องตรงต่อเวลาสิ"
L3_1.m_Talk_VTN = "Tôi là cảnh sát đương nhiên phải đúng giờ rồi."
L3_1.m_Talk_SCN = "警察当然要守时了。"
L3_1.m_Talk_DEU = "Ich bin Polizeibeamtin. Pünktlichkeit ist meine Pflicht."
L3_1.m_Talk_FRA = "Je suis officier de police. Je me dois d'être ponctuelle."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 1700001
L4_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "그런데 그 포스터는 다 뭐야?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ところで、そのポスターはなに？"
L4_1.m_Talk_ENG = "By the way, what are those posters?"
L4_1.m_Talk_TWN = "那些海報是什麼？"
L4_1.m_Talk_THA = "ว่าแต่ โปสเตอร์พวกนั้นมันอะไรน่ะ?"
L4_1.m_Talk_VTN = "Nhân tiện, đó là gì thế?"
L4_1.m_Talk_SCN = "那些海报是什么？"
L4_1.m_Talk_DEU = "Übrigens, was sind das für Plakate?"
L4_1.m_Talk_FRA = "Mais sinon, c'est quoi ces affiches ?"
