L7_1 = {}
L7_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 1700001
L7_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SOYEONG_POLICE_NULL_NULL"
L7_1.m_Pos = "R"
L7_1.m_Talk_KOREA = "이번에 저희가 붙이러 다녀야 될 현상수배서죠."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "今から私たちが貼らなければならない指名手配書です。"
L7_1.m_Talk_ENG = "Wanted posters, for you and I to put up out there today."
L7_1.m_Talk_TWN = "是我們這次要張貼的懸賞通緝令。"
L7_1.m_Talk_THA = "โปสเตอร์ประกาศจับค่ะ ที่ฉันกับคุณต้องเอาไปข้างนอกกันวันนี้"
L7_1.m_Talk_VTN = "Là bài đăng truy nã, để tôi và cô dán ngoài đường hôm nay."
L7_1.m_Talk_SCN = "是我们要张贴的悬赏通缉令。"
L7_1.m_Talk_DEU = "Fahndungsplakate, die wir heute draußen aufhängen können."
L7_1.m_Talk_FRA = "Des avis de recherche, que vous et moi allons placarder aujourd'hui."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 1700001
L8_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "SOYEONG_POLICE_NULL_NULL"
L8_1.m_Pos = "R"
L8_1.m_Talk_KOREA = "리플레이서 사태 이후로 인력이 없어서 지지부진한 사건들이 꽤 늘었잖아요."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "リプレイサーの事件以降、人手不足で\n捜査が進まない事件がかなり増えてきたじゃないですか。"
L8_1.m_Talk_ENG = "Since the Replacer incident, we've been slow at solving crimes due to a lack of manpower."
L8_1.m_Talk_TWN = "克隆事件發生後，我們人手不足，導致很多案件毫無進展。"
L8_1.m_Talk_THA = "ตั้งแต่มีเหตุการณ์รีเพลสเซอร์ เราก็แก้ปัญหาอาชญากรรมได้ช้าเพราะขาดกำลังพลค่ะ"
L8_1.m_Talk_VTN = "Kể từ vụ Người Nhân Bản, chúng ta đã chậm trễ rất nhiều trong việc giải quyết tội phạm do thiếu nhân lực.  "
L8_1.m_Talk_SCN = "克隆事件发生后，人手不足导致很多案件毫无进展。"
L8_1.m_Talk_DEU = "Seit dem Replacer-Zwischenfall sind wir aufgrund von Personalmangel nur langsam in der Lage, Verbrechen aufzuklären."
L8_1.m_Talk_FRA = "Depuis l'affaire des substituts, notre rapidité à résoudre les enquêtes est en baisse du fait de notre manque de personnel."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 1700001
L9_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L9_1.m_Pos = "L"
L9_1.m_Talk_KOREA = "그 얘기는 들었어. 시민들의 협조를 받으려고 한단 말이지."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "その話は聞いた。それで市民に協力を求めるわけね。"
L9_1.m_Talk_ENG = "So I've heard. And that's why we're going to ask the citizens for help."
L9_1.m_Talk_TWN = "這我也聽說了，是想要尋求市民的幫助吧。"
L9_1.m_Talk_THA = "ฉันก็ได้ยินมาอย่างนั้น และเพราะอย่างนั้นเราก็เลยต้องขอให้พลเมืองช่วย"
L9_1.m_Talk_VTN = "Rõ rồi. Và đó là lý do tại sao chúng ta sẽ nhờ người dân giúp đỡ."
L9_1.m_Talk_SCN = "我也听说了，想要寻求市民的帮助吧。"
L9_1.m_Talk_DEU = "Das ist mir auch zu Ohren gekommen – deshalb werden wir die Bürger um Hilfe bitten."
L9_1.m_Talk_FRA = "J'ai entendu ça. Et c'est la raison pour laquelle on va demander l'aide des citoyens."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 1700001
L10_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_HATE"
L10_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L10_1.m_Pos = "L"
L10_1.m_Talk_KOREA = "......그런데 인력이 부족하다면서 우리는 왜 수배서나 붙이러 다녀야 되는 거야?"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "……ところで、人手不足だと言ってるのに\nなんで指名手配書なんか貼りに行かなきゃならないの？"
L10_1.m_Talk_ENG = "But if manpower is the problem, shouldn't we use ours to solve crimes, rather than putting up these posters?"
L10_1.m_Talk_TWN = "……可是妳都說人手不足了，為什麼我們還要去貼通緝令呢？"
L10_1.m_Talk_THA = "แต่ถ้าปัญหาอยู่ที่กำลังพล ทำไมเราไม่ใช้กำลังพลที่ของเราสองคนไปแก้ปัญหาอาชญากรรมแทนที่จะไปแปะโปสเตอร์พวกนี้ล่ะ?"
L10_1.m_Talk_VTN = " Nhưng nếu nhân lực là vấn đề, không phải chúng ta nên sử dụng nhân viên của mình để giải quyết tội phạm, thay vì dán những tấm áp phích này sao? "
L10_1.m_Talk_SCN = "……可是人手不足，为什么还要让我们去贴通缉令？"
L10_1.m_Talk_DEU = "Aber wenn Personalmangel das Problem ist, sollten wir unsere Arbeitskraft nicht lieber zur Aufklärung von Verbrechen einsetzen, anstatt Plakate aufzuhängen?"
L10_1.m_Talk_FRA = "Mais si c'est la main-d'œuvre le problème, on ne devrait pas utiliser la nôtre pour résoudre des affaires plutôt que de coller des affiches ?"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 1700001
L11_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_LAUGH"
L11_1.m_CharStrID = "SOYEONG_POLICE_NULL_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "그야 이런 일로 농땡이 피워야 무서운 악당들이랑 싸우는 데 안 끌려 가니까요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "この仕事を口実にしておくと、怖い悪党と戦う現場に\n呼び出されなくて済むんです。"
L11_1.m_Talk_ENG = "Nope. We need this, to avoid getting dragged into fights with scary villains."
L11_1.m_Talk_TWN = "因為這樣就可以偷懶，不用去和可怕的壞人戰鬥了啊。"
L11_1.m_Talk_THA = "ไม่ค่ะ เราต้องมีโปสเตอร์พวกนี้เพื่อป้องกันไม่ให้ถูกลากไปสู้กับวายร้ายน่ากลัวๆ ค่ะ"
L11_1.m_Talk_VTN = "Không. Chúng ta cần nó, để tránh bị dính vào các cuộc chiến với những kẻ phản diện đáng sợ. "
L11_1.m_Talk_SCN = "因为这样就可以偷懒不用去和可怕的坏人战斗啊。"
L11_1.m_Talk_DEU = "Nein. Es ist eine Chance für uns, nicht in Kämpfe mit unheimlichen Bösewichten verwickelt zu werden."
L11_1.m_Talk_FRA = "Nan. Nous devons faire ça, pour éviter de nous faire à nouveau entraîner dans des affrontements contre d'affreux super-vilains."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 1700001
L12_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "SOYEONG_POLICE_NULL_NULL"
L12_1.m_Pos = "R"
L12_1.m_Crash = 35
L12_1.m_Talk_KOREA = "자자, 경정님도 오셨겠다 얼른 가죠!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "さあ、警視様も出勤したことですし、早く行きましょう！"
L12_1.m_Talk_ENG = "Alright, now that you're here, let's go!"
L12_1.m_Talk_TWN = "好了，警正大人既然也來了，那我們快出發吧！"
L12_1.m_Talk_THA = "เอาล่ะค่ะ ในเมื่อคุณก็มาแล้ว เราก็ไปกันเลย!"
L12_1.m_Talk_VTN = "Được rồi, giờ cô đã đến, đi thôi!"
L12_1.m_Talk_SCN = "好了，既然警长大人也来了，咱们快出发吧！"
L12_1.m_Talk_DEU = "Okay … Nun, da du hier bist, können wir loslegen."
L12_1.m_Talk_FRA = "Très bien, maintenant que vous êtes là, allons-y !"
