L19_1.m_Talk_KOREA = "<color=#ffd34c>연쇄 동물 납치범을 찾습니다. 실종된 동물들을 목격하신 분은 관할 경찰서로 연락 주세요</color>......"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "<color=#ffd34c>連続動物拉致事件の容疑者を捜しています。\n失踪した動物たちを目撃した方は管轄の警察署までご連絡ください</color>……"
L19_1.m_Talk_ENG = "<color=#ffd34c>Wanted: A serial animal abductor. If you believe you've witnessed animal abduction, please contact your local police station</color>..."
L19_1.m_Talk_TWN = "<color=#ffd34c>尋找動物連環綁架犯。若目擊到失蹤的動物，請聯絡管轄區的警察局</color>……"
L19_1.m_Talk_THA = "<color=#ffd34c>ประกาศจับ: ผู้ลักพาตัวสัตว์ต่อเนื่อง หากเชื่อว่าคุณพบการลักพาตัวสัตว์ โปรดติดต่อสถานีตำรวจในพื้นที่</color>..."
L19_1.m_Talk_VTN = "<color=#ffd34c>Truy nã: Một kẻ bắt cóc động vật hàng loạt. Nếu bạn tin rằng bạn đã chứng kiến vụ bắt cóc thì vui lòng liên hệ với đồn cảnh sát địa phương</color>... "
L19_1.m_Talk_SCN = "<color=#ffd34c>寻找动物连环绑架犯。若看到失踪的动物，请联系管辖警察局</color>……"
L19_1.m_Talk_DEU = "<color=#ffd34c>Gesucht: Serien-Tierentführer. Wenn Sie glauben, Zeuge einer Tierentführung geworden zu sein, wenden Sie sich bitte an Ihre örtliche Polizeidienststelle</color> …"
L19_1.m_Talk_FRA = "<color=#ffd34c>On recherche : Un ravisseur d'animaux en série. Si vous pensez avoir été témoin de l'enlèvement d'un animal, veuillez contacter votre commissariat de police local</color>..."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 1700001
L20_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_StartBGMFileName = "THEMA_WHITERABBIT"
L20_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE"
L20_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "호진 언니, 이 포스터 어디서 났어요?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "マユミさん、このポスターどこでもらいました？"
L20_1.m_Talk_ENG = "Hojin, where did you get this poster?"
L20_1.m_Talk_TWN = "鎬眞姐，這個海報是從哪來的？"
L20_1.m_Talk_THA = "ไปเอาโปสเตอร์นี่มาจากไหนอะโฮจิน?"
L20_1.m_Talk_VTN = "Hojin, cô đã lấy tờ áp phích này ở đâu thế?"
L20_1.m_Talk_SCN = "潇潇姐，这个海报是从哪来的？"
L20_1.m_Talk_DEU = "Hojin, woher hast du das Plakat?"
L20_1.m_Talk_FRA = "Hojin, où as-tu trouvé cette affiche ?"
