L23_1 = {}
L23_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 1700001
L23_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "우리 동네 여기저기에 잔뜩 붙어 있었어."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "そこでもらったの。街のあちこちにいっぱい貼られてたから。"
L23_1.m_Talk_ENG = "It was put up here and there in the neighborhood."
L23_1.m_Talk_TWN = "我們家附近到處都貼滿了這個海報。"
L23_1.m_Talk_THA = "มันแปะอยู่ตรงนั้นตรงนี้แถวนี้ล่ะ"
L23_1.m_Talk_VTN = "Nó xuất hiện khắp khu phố mà."
L23_1.m_Talk_SCN = "我们家附近到处都贴满了。"
L23_1.m_Talk_DEU = "Es wurde hier und da in der Nachbarschaft aufgehängt."
L23_1.m_Talk_FRA = "Il y en a un petit peu partout dans le quartier."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 1700001
L24_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_DESPAIR"
L24_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "어른들이 그러는데 며칠 전에 알렉산더도 사라졌대."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "大人たちが言ってたけど、数日前にアレクサンダーも消えたって。"
L24_1.m_Talk_ENG = "Some grownups said that Alexander also disappeared a few days ago."
L24_1.m_Talk_TWN = "我聽大人們說，幾天前，亞歷山大也失蹤了。"
L24_1.m_Talk_THA = "มีผู้ใหญ่บอกว่าอเล็กซานเดอร์อะไรนั่นหายไปสองสามวันแล้ว"
L24_1.m_Talk_VTN = "Vài người lớn nói là Alexander cũng đã biến mất vài ngày trước."
L24_1.m_Talk_SCN = "我听大人们说几天前亚历山大也失踪了。"
L24_1.m_Talk_DEU = "Einige Erwachsene sagten, dass Alexander vor ein paar Tagen verschwunden ist."
L24_1.m_Talk_FRA = "Certains adultes ont dit qu'Alexander avait aussi disparu depuis quelques jours."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 1700001
L25_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "알렉산더는 누군가, 호진 대원?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "マユミ隊員、アレクサンダーとは誰のことだ？"
L25_1.m_Talk_ENG = "Who's this Alexander, Operative Hojin?"
L25_1.m_Talk_TWN = "亞歷山大是誰啊，鎬眞隊員？"
L25_1.m_Talk_THA = "อเล็กซานเดอร์ไหนเหรอเจ้าหน้าที่โฮจิน?"
L25_1.m_Talk_VTN = "Ai là Alexander thế, Đặc Vụ Hojin?"
L25_1.m_Talk_SCN = "亚历山大是谁，潇潇队员？"
L25_1.m_Talk_DEU = "Wer ist Alexander, Agentin Hojin?"
L25_1.m_Talk_FRA = "Qui est cet Alexander, agent Hojin ?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 1700001
L26_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L26_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Talk_KOREA = "야채 가게 할아버지가 키우는 웰시 코기. 우리 동네 귀여움 일등이야."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "八百屋のおじいさんが飼ってるウェルシュ・コーギーだよ。\nこの街で一番可愛いの。"
L26_1.m_Talk_ENG = "The greengrocer's Welsh Corgi. He's the cutest thing in the neighborhood."
L26_1.m_Talk_TWN = "是蔬菜店爺爺養的一隻柯基犬，在我們街上是超級可愛的狗狗。"
L26_1.m_Talk_THA = "เวลช์คอร์กี้ของคนขายผักผลไม้ไง เขาเป็นสิ่งที่น่ารักที่สุดในละแวกนี้เลยนะ"
L26_1.m_Talk_VTN = "Con chó Corgi xứ Wales của anh bán rau. Anh ấy là người dễ thương nhất trong khu phố. "
L26_1.m_Talk_SCN = "是蔬菜店爷爷养的一只柯基犬，超级可爱的。"
L26_1.m_Talk_DEU = "Der Welsh Corgi des Gemüsehändlers – und das niedlichste Ding in der Nachbarschaft!"
L26_1.m_Talk_FRA = "Le Welsh Corgi du marchand de fruits et légumes. On ne fait pas plus mignon dans le quartier."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "SCHOOL_PART1_NODE1_PROLOGUE@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 1700001
L27_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_LAUGH"
L27_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L27_1.m_Pos = "R"
L27_1.m_Talk_KOREA = "여기 사진도 찍어 뒀어. 볼래?"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "写真があるんだけど、見る？"
L27_1.m_Talk_ENG = "Here, I've got his photo, too. Want to see?"
L27_1.m_Talk_TWN = "我這裡有照片，要看嗎？"
L27_1.m_Talk_THA = "นี่ ฉันมีรูปเขาด้วย อยากดูมั้ย?"
L27_1.m_Talk_VTN = "Đây, tôi có cả ảnh của nó đây. Có muốn xem không?"
L27_1.m_Talk_SCN = "我这儿有照片，要看吗？"
L28_1 = "Hier, ich habe auch ein Foto von ihm. Willst du mal sehen?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'ai même sa photo. Vous voulez la voir ?"
L27_1.m_Talk_FRA = L28_1
