L28_1.m_Crash = 20
L29_1 = "오오...... 괴, 굉장히 사랑스러운 털뭉치다......"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "おぉ……す、すごく可愛らしいモフモフだな……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Ooh... S-such an adorable-looking furball!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "噢噢……好、好可愛的小毛團……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "โอ้... ไอ้ตัวบอลขนหน้าตาน่ารัก!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ố ồ... Q-quả là một cục bông dễ thương!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "噢噢……好，好可爱的小毛团……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Oh … Was für ein entzückendes Fellknäuel!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ooh... M-Mais quelle adorable petite boule de poil !"
