L31_1 = 30
L30_1.m_Crash = L31_1
L31_1 = "이렇게 귀여운 강아지를 납치해 가다니, 나쁜 사람들 짓이 분명해!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "こんなに可愛い犬をさらうなんて、きっと悪い人たちの仕業だよ！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Whoever has kidnapped this cute dog, he's got to be a bad person."
L30_1.m_Talk_ENG = L31_1
L31_1 = "竟然綁架這麼可愛的小狗，一定是壞人做的！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ใครที่ลักพาตัวน้องหมาน่ารักแบบนี้ไปได้ต้องเป็นคนไม่ดีแน่ๆ เลย"
L30_1.m_Talk_THA = L31_1
L31_1 = "Bất kỳ ai đã bắt cóc con chó này đều chắc chắn là một kẻ xấu xa."
L30_1.m_Talk_VTN = L31_1
L31_1 = "竟然绑架这么可爱的小狗，一定是坏人干的！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wer auch immer diesen süßen Hund entführt hat, muss ein schlechter Mensch sein."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Celui ou celle qui a enlevé ce chien doit être une bien mauvaise personne."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SCHOOL_PART1_NODE1_PROLOGUE@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 1700001
L31_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "사라진 동물들을 찾아서 다시 보금자리로 돌려 보내 주자!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "いなくなった動物たちを探し出して、家に帰してあげよう！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Let's find the missing animals and send them back home!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "讓我們找到失蹤的動物，送它們回家吧！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไปตามหาสัตว์ที่หายไปแล้วส่งกลับบ้านกันเถอะ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hãy tìm những động vật mất tích và đưa chúng về nhà!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "我们要找到失踪的动物，送它们回家！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Lasst uns die vermissten Tiere finden und zurück nach Hause bringen!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Retrouvons les animaux disparus et ramenons-les chez eux !"
L31_1.m_Talk_FRA = L32_1
