L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 1700001
L34_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_PRIDE"
L34_1.m_Face = L35_1
L34_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L34_1.m_Pos = "L"
L35_1 = "들었나, 스미스 병장. 새롭게 태어난 심판의 탄환을 선보일 기회다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "聞いたか、スミス兵長。生まれ変わった審判の弾丸を披露するチャンスだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Hear that, Sergeant Smith? We've got a chance to showcase our newborn bullets of punishment."
L34_1.m_Talk_ENG = L35_1
L35_1 = "聽到了嗎，史密斯兵長，這是讓嶄新的審判子彈亮相的機會。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ได้ยินมั้ย จ่าสมิธ? เรามีโอกาสได้อวดกระสุนลงทัณฑ์เกิดใหม่กันแล้วนะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nghe thấy chưa, Trung Sĩ Smith? Chúng ta có cơ hội để biểu diễn loại đạn trừng phạt mới đấy. "
L34_1.m_Talk_VTN = L35_1
L35_1 = "听到了吗，史密斯兵长，是时候让崭新的审判之子弹亮相了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hast du gehört, Sergeant Smith? Wir haben die Chance, unsere neuen Strafkugeln zu präsentieren."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Vous entendez ça, sergent Smith ? Nous allons enfin pouvoir faire la démonstration de nos nouvelles balles de châtiment."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SCHOOL_PART1_NODE1_PROLOGUE@35#Talk"
