L36_1 = 30
L35_1.m_Crash = L36_1
L36_1 = "좋아, 그럼 지금 바로 알렉산더를 찾으러 가자!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "よし、それじゃあ今すぐアレクサンダーを探しに行こう！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Alright, then let's go find Alexander now!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "好，我們現在就去找亞歷山大吧！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอาละ งั้นก็ไปตามอเล็กซานเดอร์กันเลย!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Được, vậy hãy đi tìm Alexander nào!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "好，现在就去找亚历山大吧！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Okay, lass uns Alexander suchen gehen!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Très bien, partons à la recherche d'Alexander dans ce cas !"
L35_1.m_Talk_FRA = L36_1
