L37_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L37_1.m_Pos = "C"
L37_1.m_Crash = 40
L38_1 = "앗, 역시 호진 언니! 무슨 단서가 있어요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "さすがマユミさん！　何か手がかりがあるんですか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Ooo, yes, Hojin! So, got any leads?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "啊，不愧是鎬眞姐姐！有什麼線索嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โอออ จริงสิโฮจิน! มีเบาะแสอะไรบ้างมั้ยอะ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ồ, được, Hojin! Có đầu mối gì chưa?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "啊，不愧是潇潇姐姐！有什么线索吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Oh ja, Hojin! Hast du irgendwelche Hinweise?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ooh, oui, Hojin ! Alors, tu as une piste ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SCHOOL_PART1_NODE1_PROLOGUE@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 1700001
L38_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_LAUGH"
L38_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "아니? 모르는데? 어디로 가면 돼?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "うーん、わからないかも。どこに行けばいいかな？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Erm, no. Where do we start?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "沒有啊？我不知道，應該去哪裡找呀？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เอิ่ม ไม่เลย เราเริ่มยังไงกันดีนะ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ừm, không có. Chúng ta bắt đầu từ đâu đây?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "没有啊？我不知道，应该去哪里呀？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Äh, nein. Wo sollen wir anfangen?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Euh, non. Par où commencer ?"
L38_1.m_Talk_FRA = L39_1
