L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 1700001
L42_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_DESPAIR"
L42_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L42_1.m_Pos = "L"
L43_1 = "음...... 폰으로 찾아 보니까 호진 언니네 말고도 여기저기서 같은 일이 일어났대요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "うーん……スマホで調べてみたら、\nいろんなところで同じような事件が起きたって。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Mm... I checked on my phone, and the same thing has happened in many other places as well."
L42_1.m_Talk_ENG = L43_1
L43_1 = "唔……我用手機查了一下，除了鎬眞姐姐家之外，其他地方也發生了同樣的事情。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อืม... ฉันเช็คโทรศัพท์ดูแล้วนะ มีเรื่องแบบนี้เกิดขึ้นหลายที่เหมือนกัน"
L42_1.m_Talk_THA = L43_1
L43_1 = " Mm... Tôi đã kiểm tra điện thoại của mình và chuyện tương tự cũng xảy ra ở nhiều nơi khác.  "
L42_1.m_Talk_VTN = L43_1
L43_1 = "唔……我用手机查了一下，除了潇潇姐姐公寓之外，其他地方也发生了类似的事情。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich habe auf meinem Handy nachgesehen. Das Gleiche ist auch an vielen anderen Orten passiert."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Hmm... J'ai vérifié sur mon téléphone, et la même chose s'est déroulée dans plein d'autres endroits en fait."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCHOOL_PART1_NODE1_PROLOGUE@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 1700001
L43_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L43_1.m_Pos = "R"
L44_1 = "정말? 그럼 여러 명일 수도 있겠네?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "本当に？　じゃあ、複数人による犯行かもしれないよね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Really? Then, there could be multiple perps."
L43_1.m_Talk_ENG = L44_1
L44_1 = "真的嗎？這麼說犯人可能有好幾個囉？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "จริงเหรอ งั้นก็อาจมีผู้ก่อการหลายคนนะสิ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Thật ư? Vậy chắc hẳn là có nhiều tội phạm. "
L43_1.m_Talk_VTN = L44_1
L44_1 = "真的？这么说犯人可能有好几个？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wirklich? Dann könnte es mehrere Täter geben."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Vraiment ? Il pourrait y avoir plusieurs suspects alors."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SCHOOL_PART1_NODE1_PROLOGUE@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 1700001
L44_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L44_1.m_Pos = "L"
L45_1 = "네. 저희끼리만 갔다가 누가 다치기라도 하면......"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "はい。僕たちだけで行って、もし誰か怪我でもしたら……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yes. This could be too dangerous for just the three of us to handle, too."
L44_1.m_Talk_ENG = L45_1
L45_1 = "沒錯，就我們幾個去，萬一出了事……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ใช่ นี่อาจจะอันตรายเกินกว่าเราสามคนจะจัดการเองด้วยนะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đúng thế. Chỉ ba người chúng ta xử lý vụ này có thể quá nguy hiểm.  "
L44_1.m_Talk_VTN = L45_1
L45_1 = "没错，就我们几个去万一出了事……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ja, und es könnte zu gefährlich werden nur für uns drei."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oui, ça pourrait aussi être trop dangereux pour qu'on s'en occupe seules."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
