L47_1 = "UNIT_PRIDE"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L46_1.m_Pos = "C"
L46_1.m_Crash = 20
L47_1 = "후, 후훗...... 그렇다면 어쩔 수 없지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふ、ふふっ……なら、仕方ないか。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hah, hah hah. I guess we don't have a choice, then."
L46_1.m_Talk_ENG = L47_1
L47_1 = "呵，呵呵……那沒辦法了。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฮ่า ฮ่าฮ่า ฉันว่าถ้างั้นก็คงไม่มีทางเลือกแล้วล่ะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ha ha ha. Tôi đoán lúc đó chúng ta không có lựa chọn nào khác."
L46_1.m_Talk_VTN = L47_1
L47_1 = "呵，呵呵……那没办法了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hahaha … Dann bleibt uns wohl keine Wahl."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ha ha ha. J'imagine que nous n'avons pas le choix dans ce cas."
L46_1.m_Talk_FRA = L47_1
