L48_1 = "SCHOOL_PART1_NODE1_PROLOGUE@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 1700001
L47_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "베테랑인 본관은 문제없지만, 하림 대장과 호진 대원의 안전을 위해 작전은 재고해야겠군."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ベテランである本官は問題ないが、\nウサギ隊長とマユミ隊員の安全のために、作戦は再考することにしよう。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I could handle it just fine, but I understand if you two are too worried to carry on with it."
L47_1.m_Talk_ENG = L48_1
L48_1 = "像本官這種老兵是沒什麼問題的，但為了夏琳隊長和鎬眞隊員的安全，這個作戰得重新考慮一下了。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันจัดการเองได้สบายๆ แต่ก็เข้าใจได้นะถ้าเธอสองคนจะกังวลถ้าต้องไปต่อน่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi có thể giải quyết nó dễ như ăn kẹo thôi, nhưng tôi hiểu nếu hai người quá lo lắng. "
L47_1.m_Talk_VTN = L48_1
L48_1 = "像本官这种老手是没什么问题的，但为了夏琳队长和潇潇队员的安全，还是重新考虑一下吧。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich würde schon klarkommen – aber ich verstehe, wenn ihr zwei zu besorgt seid, um es durchzuziehen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je pourrais très bien m'en occuper moi-même, mais je comprends que vous soyez trop inquiètes pour continuer."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
