L5_1.m_Crash = 20
L6_1 = "와, 여기 학생회 건물 맞죠? 처음 와 봐요!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "わぁ、ここって生徒会の建物ですよね？　初めて来ました！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Whoa, this is the Student Council building, right? I've never been here before!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "哇，這是學生會大樓吧？我還是第一次來呢！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "โห นี่มันตึกสภานักเรียนใช่มั้ยอะ? ไม่เคยมาเลย!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Oa, đây là tòa nhà Hội Đồng Học Sinh phải không? tôi chưa bao giờ đến đây cả!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "哇，这是学生会主楼吧？我还是第一次来呢！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wow, das ist das Gebäude des Schülerparlaments, oder? Ich war noch nie hier!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ouah, c'est le bâtiment du conseil des élèves, c'est ça ? Je n'étais encore jamais venue ici !"
L5_1.m_Talk_FRA = L6_1
