L7_1 = "SCHOOL_PART1_NODE1_PROLOGUE@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 1700001
L6_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L6_1.m_Pos = "L"
L7_1 = "그런데 언니, 우리 이렇게 마음대로 들어와도 돼요?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ところで、マユミさん。勝手に入っていいんですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But Hojin, are you sure we can get in without telling anyone?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "不過姐姐，我們這樣隨便進來，真的沒問題嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่ว่าโฮจิน เธอแน่ใจเหรอว่าเราเข้าไปโดยไม่ต้องบอกใครได้อะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhưng Hojin à, cô có chắc là chúng ta có thể đi vào mà không cần báo cho ai không?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "不过姐姐，我们这样随便进来真的没问题吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber Hojin, bist du sicher, dass wir da reinkommen, ohne jemandem Bescheid zu geben?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais tu es sûre qu'on peut rentrer sans être invitées, Hojin ?"
L6_1.m_Talk_FRA = L7_1
