L7_1.m_Face = L8_1
L7_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L7_1.m_Pos = "R"
L8_1 = "응. 곤란한 일이 생기면 언제든지 찾아오라고 사부가 알려 줬거든."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "うん。困ったことがあったらいつでも訪ねて来いと\n師匠が教えてくれたの。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Yes. Master told me to come whenever I needed her help."
L7_1.m_Talk_ENG = L8_1
L8_1 = "嗯，我師父說過，遇到麻煩可以隨時來找她。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ได้สิ อาจารย์บอกฉันว่าต้องการความช่วยเหลือเมื่อไหร่ก็ให้มา"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ừ. Sếp bảo tớ cứ đến khi nào cần giúp đỡ."
L7_1.m_Talk_VTN = L8_1
L8_1 = "嗯，我师傅说过，遇到麻烦可以随时来找她。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja. Die Meisterin sagte, ich solle kommen, wann immer ich ihre Hilfe brauche."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oui. Le maître m'a dit que je pouvais venir chaque fois que j'avais besoin de son aide."
L7_1.m_Talk_FRA = L8_1
