L15_1.m_fTalkTime = 0.03
L16_1 = "屋上だ！　狙撃手か！　みんな、隠れろ！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "A possible sniper on the rooftop! Everyone, take cover!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "在屋頂！是狙擊手嗎！全員找掩護！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "อาจมีสไนเปอร์บนหลังคานะ! ทุกคน หาที่กำบัง!"
L15_1.m_Talk_THA = L16_1
