L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "신성한 학생회에 아무것도 모르는 어린 후배들을 데려 오다니 놀랍군요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "神聖なる生徒会に、何も知らない\n若い後輩たちを連れてくるとは驚きました。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You dared bring ignorant juniors to the sacred ground of the Student Council."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你竟然把年幼的後輩帶到了神聖的學生會。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "กล้าพารุ่นน้องที่ไม่รู้เรื่องรู้ราวมายังพื้นที่ศักดิ์สิทธิ์ของสภานักเรียนแบบนี้"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cô dám đưa đám đàn em ngu dốt đến thánh địa của Hội Đồng Học Sinh sao. "
L21_1.m_Talk_VTN = L22_1
L22_1 = "你竟然把年幼的后辈带到了神圣的学生会。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Du hast es gewagt, unkundige Jugendliche auf den heiligen Boden des Schülerparlaments zu bringen."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vous avez osé emmener des étudiants de premier cycle profanes sur les terres sacrées du conseil des élèves."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "SCHOOL_PART1_NODE1_PROLOGUE@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 1700001
L22_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "PRESIDENT_SCHOOL_QM_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "자기 행동 때문에 무슨 일이 일어날지 각오했다는 의미로 받아들여도 되겠죠?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "自分の行動の結果として何が起きても\n覚悟はできている、という意味にとらえてもよいでしょうか？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Can I take it that you're prepared for the consequences, whatever they are?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "妳的行動會引起怎麼樣的結果，我就當作妳已經有心理準備了。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันถือว่าพวกเธอเตรียมตัวรับผลที่จะตามมากันแล้วได้มั้ยคะ ไม่ว่าจะคืออะไรก็ตาม?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi có thể hiểu rằng cô đã chuẩn bị lãnh hậu quả, bất kể chúng là gì phải không? "
L22_1.m_Talk_VTN = L23_1
L23_1 = "我可以理解为你能为你的莽撞行为负责是吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Seid ihr bereit, die Konsequenzen zu tragen, wie auch immer sie aussehen mögen?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Est-ce que je peux en conclure que vous êtes prêtes à en subir les conséquences, quelles qu'elles soient ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
