L29_1 = "PRESIDENT_SCHOOL_QM_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "달콤한 음식은 긴장을 풀어주죠."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "甘いものは緊張をほぐしてくれます。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Sweet food helps you relax."
L28_1.m_Talk_ENG = L29_1
L29_1 = "甜食可以緩解緊張的情緒。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ของกินหวานๆ ช่วยให้ผ่อนคลายนะคะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Đồ ngọt giúp người ta cảm thấy thư giãn mà."
L28_1.m_Talk_VTN = L29_1
L29_1 = "甜食可以缓解紧张的情绪。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Süßes Essen hilft, sich zu entspannen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "La nourriture sucrée aide à la relaxation."
L28_1.m_Talk_FRA = L29_1
