L30_1 = "SCHOOL_PART1_NODE1_PROLOGUE@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1700001
L29_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L29_1.m_bWaitClick = true
