L30_1 = "PRESIDENT_SCHOOL_QM_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "후배 손님들을 위해 항상 넉넉히 준비해 두고 있으니 많이들 먹어요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "後輩のお客さんのためにいつもたっぷり\n用意してますので、好きなだけどうぞ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I always have some on hand for guests like you. Please, help yourselves."
L29_1.m_Talk_ENG = L30_1
L30_1 = "這些是隨時專為你們這些後輩準備的，多吃點吧。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันมีเผื่อไว้ให้แขกแบบพวกหนูตลอดและค่ะ เพราะงั้น ช่วยเหลือตัวเองนะคะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi luôn có sẵn một ít bánh quỹ cho những khách như cô. Cứ tự nhiên đi. "
L29_1.m_Talk_VTN = L30_1
L30_1 = "这些都是专为你们这些后辈准备的，多吃点吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Für Gäste wie euch habe ich immer welche vorrätig. Bitte bedient euch."
L29_1.m_Talk_DEU = L30_1
L30_1 = "J'en ai toujours à disposition pour les invités comme vous. Je vous en prie, servez-vous."
L29_1.m_Talk_FRA = L30_1
