L33_1.m_Pos = "L"
L33_1.m_Crash = 20
L34_1 = "네? 이 언니가 호진 언니가 말한 사부님이세요?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "え？　このお姉さんがマユミさんの言っていた師匠ですか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Err? Hojin, is she the Master you told us about?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "嗯？這個姐姐就是鎬眞姐說的師父嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เอ๋? เธอคืออาจารย์คนที่ว่าเหรอโฮจิน?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ơ? Hojin, cô ấy là Sếp là cô đã kể với chúng tôi sao?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "嗯？这个姐姐就是潇潇姐姐说的师傅吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hä? Hojin, ist sie die Meisterin, von der du uns erzählt hast?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Euh ? Hojin, c'est elle le maître dont tu nous as parlé ?"
L33_1.m_Talk_FRA = L34_1
