L34_1.m_Pos = "R"
L35_1 = "응. 그리고 우리 아카데미의 총학생회장이야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "うん。そしてアカデミーの生徒会長なのよ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Yes. She's also the Student President of the Academy."
L34_1.m_Talk_ENG = L35_1
L35_1 = "對，也是我們學院的學生會長。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ใช่ แล้วก็เป็นประธานนักเรียนของสถาบันด้วย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ừ. Cô ấy là chủ tịch học sinh của Học Viện."
L34_1.m_Talk_VTN = L35_1
L35_1 = "对，也是我们学院的学生会长。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ja. Sie ist zudem die Schülerpräsidentin der Akademie."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Oui. C'est aussi la présidente du conseil des élèves de l'Académie."
L34_1.m_Talk_FRA = L35_1
