L38_1.m_fWaitTime = 0
L39_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "근래 처리할 업무가 많다 보니 새로 온 전학생과 인사를 나눌 여유도 없었군요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "近頃は業務が多くて新しい転校生に挨拶する暇もなかったんです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I've been so busy working that I didn't have time to say hello to you new transfer students."
L38_1.m_Talk_ENG = L39_1
L39_1 = "最近很多事務，都沒有時間問候新來的轉校生。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฉันมัวแต่ทำงานยุ่งอยู่เลยไม่มีเวลามาทักทายพวกคุณที่เพิ่งย้ายมาเรียนที่นี่กันเลยค่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi quá bận rộn với công việc nên không có thời gian để chào các bạn - những học sinh mới chuyển trường.  "
L38_1.m_Talk_VTN = L39_1
L39_1 = "最近事务有些繁忙，都没来得及问候新来的转校生。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich hatte so viel zu tun, dass ich keine Zeit hatte, euch Neuen Hallo zu sagen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je suis tellement absorbée par le travail que je n'ai même pas pris le temps d'accueillir les nouveaux élèves comme vous."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SCHOOL_PART1_NODE1_PROLOGUE@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 1700001
L39_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_DESPAIR"
L40_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "학생회장으로서 충분히 노력하고 있다고 생각했지만, 저도 아직 멀었네요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "生徒会長として十分努力していると\n思っていましたが、私もまだまだですね。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Clearly, I'm not as good Student President as I thought I was."
L39_1.m_Talk_ENG = L40_1
L40_1 = "身為學生會長，我雖然自認為很努力，但還遠遠不夠呢。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เห็นได้ชัดว่า ฉันไม่ได้เป็นประธานนักเรียนที่ดีเท่าที่ตัวเองคิด"
L39_1.m_Talk_THA = L40_1
L40_1 = "Rõ ràng thì tôi không phải là một chủ tịch học sinh giỏi giang như tôi nghĩ."
L39_1.m_Talk_VTN = L40_1
L40_1 = "虽然我自认为很努力，但还远远不够呢。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Offenbar bin ich keine so gute Schülerpräsidentin, wie ich dachte …"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je ne suis à l'évidence pas une aussi bonne présidente que je pensais l'être."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
