L43_1 = "SCHOOL_PART1_NODE1_PROLOGUE@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 1700001
L42_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SURPRISE"
L42_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L42_1.m_Pos = "L"
L43_1 = 50
L42_1.m_Crash = L43_1
L43_1 = "앗, 아니에요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "いえっ、そんなことないです。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Oh, no."
L42_1.m_Talk_ENG = L43_1
L43_1 = "啊，沒這種事。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อ๋อไม่เลยค่ะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ồ, không."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不，不是的。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Oh nein!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh, non."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCHOOL_PART1_NODE1_PROLOGUE@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 1700001
L43_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_LAUGH"
L43_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L43_1.m_Pos = "L"
L44_1 = "그보다 멋대로 들어와서 혼날 거라고 생각했는데, 이렇게 챙겨 주셔서 놀랐어요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それより、勝手に入っちゃって怒られると\n思ったんですが、歓迎いただいて驚きました。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'm surprised for your unexpected hospitality. I thought you'd punish us for sneaking in."
L43_1.m_Talk_ENG = L44_1
L44_1 = "本來以為妳會因為我們擅自闖入生氣，沒想到妳卻這麼照顧我們。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "คุณใจดีอย่างไม่ทันตั้งตัวน่ะค่ะ นึกว่าพวกเราจะโดนทำโทษเพราะแอบเข้ามาซะแล้ว"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi rất ngạc nhiên vì sự hiếu khách bất ngờ của cô. Tôi tưởng cô sẽ trừng phạt chúng tôi vì đã lẻn vào cơ chứ ."
L43_1.m_Talk_VTN = L44_1
L44_1 = "本以为你会责怪我们擅自闯入，却没想到如此照顾我们。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich bin überrascht über eure unerwartete Gastfreundschaft. Ich dachte, wir würden bestraft werden, weil wir uns reingeschlichen haben."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je suis surprise de votre hospitalité inattendue. Je pensais que vous nous puniriez pour avoir tenté de nous introduire."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SCHOOL_PART1_NODE1_PROLOGUE@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 1700001
L44_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L44_1.m_Pos = "R"
L45_1 = "그게 바로 사부의 매력이지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "それが師匠の魅力だよ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "That's exactly why I like her."
L44_1.m_Talk_ENG = L45_1
L45_1 = "這就是我師父的魅力。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แบบนั้นไงล่ะฉันถึงชอบเธอ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đó chính là lý do mà tôi thích cô ấy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "这就是我师傅的魅力。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Das ist genau der Grund, warum ich sie so mag."
L44_1.m_Talk_DEU = L45_1
L45_1 = "C'est exactement pour ça que je l'apprécie."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SCHOOL_PART1_NODE1_PROLOGUE@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 1700001
L45_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L45_1.m_Pos = "R"
L46_1 = "분위기는 항상 무겁고 진지해 보이지만 사실 엄청 착하거든."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "いつもクールで真面目に見えるけど、とても優しいの。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "She always looks stern and serious, but she's actually very kind and friendly."
L45_1.m_Talk_ENG = L46_1
L46_1 = "雖然她看起來很嚴肅，但其實是非常善良的。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เธอดูเข้มงวดจริงจังตลอด แต่จริงๆ ใจดีและเป็นมิตรมากเลย"
L45_1.m_Talk_THA = L46_1
L46_1 = "Cô ấy luôn trông đĩnh đạc và nghiêm khắc, nhưng thực ra cô ấy rất tốt bụng và thân thiện. "
L45_1.m_Talk_VTN = L46_1
L46_1 = "虽然她看起来很严肃，其实是非常善良的。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Sie wirkt immer streng und ernst, aber eigentlich ist sie sehr nett und zugewandt."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Elle a toujours l'air sévère et grave, mais elle est en fait très gentille et amicale."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
