L48_1 = "SCHOOL_PART1_NODE1_PROLOGUE@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 1700001
L47_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L48_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "예전부터 제 인상 때문인지 학생들이 절 대하기 어려워하더군요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "昔からそのような印象のせいか、生徒たちが私と接しにくいようでした。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It's probably the way I look that keeps other students away."
L47_1.m_Talk_ENG = L48_1
L48_1 = "從以前開始，學生們就因為我的形象，都有些怕我。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อาจเพราะท่าทางฉันนี่แหละค่ะนักเรียนเลยไม่กล้าเข้าใกล้"
L47_1.m_Talk_THA = L48_1
L48_1 = "Có lẽ vẻ ngoài của tôi khiến những học sinh khác tránh xa. "
L47_1.m_Talk_VTN = L48_1
L48_1 = "可能是因为我的外表，学生们都有些怕我。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Wahrscheinlich ist es mein Aussehen, das andere Schüler abschreckt."
L47_1.m_Talk_DEU = L48_1
L48_1 = "C'est probablement mon apparence qui tient les autres élèves à distance."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SCHOOL_PART1_NODE1_PROLOGUE@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 1700001
L48_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "게다가 학생들이 친근감을 가지고 다가와야 할 학생회도 딱딱한 이미지로 굳어 버렸죠."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そのせいで生徒に親しまれるべき生徒会も\n堅いイメージになってしまいました。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And my position in the Student Council as well."
L48_1.m_Talk_ENG = L49_1
L49_1 = "也因此，本來該與學生保持親近的學生會，形象也變得非常嚴肅死板。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "และตำแหน่งในสภานักเรียนของฉันก็ด้วย"
L48_1.m_Talk_THA = L49_1
L49_1 = "Và cả vị trí của tôi trong Hội Đồng Học Sinh nữa."
L48_1.m_Talk_VTN = L49_1
L49_1 = "而且本应与学生亲近的学生会的形象也变得严肃死板。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Und auch meine Position im Schülerparlament."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ainsi que ma position au sein du conseil des élèves."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SCHOOL_PART1_NODE1_PROLOGUE@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 1700001
L49_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_PRIDE"
L49_1.m_Face = L50_1
L50_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "그래서 요즘은 학생들과 더 가까워지기 위해 아까처럼 직접 마중 나가곤 한답니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ですので、もっと親しんでいただけるよう、\n最近は先ほどのように直接出迎えたりもします。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "So, I've been trying to receive them in person like I did with you earlier, to get close to them."
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以為了拉近和學生的距離，我會像剛才一樣親自出去迎接。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันก็เลยพยายามต้อนรับนักเรียนเป็นการส่วนตัวอย่างที่ทำกับทุกคนเมื่อกี้นี่แหละค่ะ จะได้ใกล้ชิดกัน"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vì vậy, tôi đã cố gắng nghênh đón họ trực tiếp như tôi đã làm với cô trước đó, để đến gần họ. "
L49_1.m_Talk_VTN = L50_1
L50_1 = "于是为了拉近与学生的距离，我会像刚才一样亲自出去迎接。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Darum versuche ich stets, sie persönlich zu empfangen, wie ich es vorhin bei euch getan habe, um ihnen nahezukommen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Alors j'essaie de les accueillir en personne, comme je l'ai fait avec vous, pour me rapprocher d'eux."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
