L2_1 = "SCHOOL_PART1_NODE1_PROLOGUE@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 1700001
L1_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "하림 양은 좀 전부터 저를 똑바로 보지 못하는 것 같은데."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ウサギさんは、さっきから私と目を合わせてくれないようですが。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Harim, I've noticed you're avoiding eye contact with me."
L1_1.m_Talk_ENG = L2_1
L2_1 = "從剛才開始，夏琳好像就一直不敢直視我。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฮาริม ฉันสังเกตว่าเธอหลีกเลี่ยงการสบตากับฉันตลอดเลย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Harim, tôi nhận thấy là cô đã tránh nhìn vào mắt tôi."
L1_1.m_Talk_VTN = L2_1
L2_1 = "从刚才开始，夏琳好像一直不敢看我，"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Harim, mir ist aufgefallen, dass du Augenkontakt mit mir meidest."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Harim, j'ai remarqué que vous évitiez mon regard."
L1_1.m_Talk_FRA = L2_1
