L5_1 = "SCHOOL_PART1_NODE1_PROLOGUE@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 1700001
L4_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "L_M_I"
L4_1.m_Pos = L5_1
L5_1 = "아직도 제가 어렵게 느껴지나요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "まだ私のことを接しにくいと感じているでしょうか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Am I still making you feel uncomfortable?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "還是覺得我很難以親近嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ฉันทำให้คุณอึดอัดรึเปล่าคะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi vẫn khiến cô cảm thấy không thoải mái sao?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "还觉得我可怕吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Fühlst du dich immer noch unwohl in meiner Gegenwart?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Est-ce que je vous mets toujours mal à l'aise ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "SCHOOL_PART1_NODE1_PROLOGUE@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 1700001
L5_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_SURPRISE"
L5_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "앗, 아뇨! 무척 친절한 분이라고 생각해요!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あっ、いいえ！　とても親切な方だと思います！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh, no. I think you're very kind."
L5_1.m_Talk_ENG = L6_1
L6_1 = "啊，不是的！我覺得妳非常親切！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อ๋อ เปล่าค่ะ ฉันว่าคุณใจดีมากๆ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ồ không. Tôi nghĩ là cô rất tốt bụng mà."
L5_1.m_Talk_VTN = L6_1
L6_1 = "啊，不是的！我觉得你非常温柔！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Oh, nein … Ich finde dich sehr freundlich."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oh, non. Je pense que vous êtes très gentille."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SCHOOL_PART1_NODE1_PROLOGUE@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 1700001
L6_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "저어...... 그런데 항상 그렇게 과감한 옷차림으로 다니세요?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あの……ところで、いつもそんなに大胆な服装なんですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But erm... do you always wear bold clothes like those?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "只是……妳平時也穿得如此開放嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่ เอิ่ม... คุณแต่งตัวเตะตาแบบนี้ตลอดเหรอคะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhưng ờ... cô luôn mặc những bộ quần áo nặng nề như thế sao?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "不过……你平时也穿如此豪放的衣服吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber, äh … Trägst du immer so auffällige Kleidung?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais euh... vous portez toujours des vêtements aussi osés ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SCHOOL_PART1_NODE1_PROLOGUE@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 1700001
L7_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_LAUGH"
L8_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "L"
L8_1 = "저희 아카데미는 복식의 자유를 존중하기 위해 교복 착용을 강제하지 않기로 했어요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私たちのアカデミーは服装の自由を\n尊重するために、制服を強制しないことにしました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The Academy has decided not to force its uniform on its students; to respect their freedom of dress."
L7_1.m_Talk_ENG = L8_1
L8_1 = "本學院尊重學生的穿著自由，不會強制要求學生穿校服。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ทางสถาบันตัดสินใจไม่บังคับให้นักเรียนใส่เครื่องแบบค่ะ เพื่อเคารพเสรีภาพในการแต่งกาย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Học Viện đã quyết định không bắt buộc học sinh phải mặc đồng phục rồi; để tôn trọng quyền tự do ăn mặc của họ. "
L7_1.m_Talk_VTN = L8_1
L8_1 = "我们学院尊重学生个性，穿衣自由，不会强制要求学生穿校服。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Die Akademie hat beschlossen, den Schülern keine Uniform aufzudrängen, sondern ihre freie Kleiderwahl zu respektieren."
L7_1.m_Talk_DEU = L8_1
L8_1 = "L'Académie a décidé de ne pas imposer d'uniforme à ses élèves afin de respecter leur liberté vestimentaire."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SCHOOL_PART1_NODE1_PROLOGUE@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 1700001
L8_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "L"
L9_1 = "저 또한 학생들의 다양한 개성을 수렴해야 하는 학생회장으로서, 타의 귀감이 되기 위해 이렇게 입기 시작했답니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私も生徒の多様性を受け入れるべき生徒会長として、\n皆さんの模範になるためこのような服装になりました。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So, as their representative, I started wearing clothes like these to show them that they can wear whatever they want to express their uniqueness."
L8_1.m_Talk_ENG = L9_1
L9_1 = "而作為必需包容學生不同個性的學生會長，就得以身作則才行，所以我才開始這樣穿的。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ดังนั้น ในฐานะตัวแทนของพวกเขา ฉันก็เลยเริ่มแต่งตัวแบบนี้\nเพื่อให้เห็นว่าพวกเขาจะใส่อะไรก็ได้ตามต้องการเพื่อแสดงเอกลักษณ์ของตัวเองออกมากันค่ะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vì vậy, với tư cách là người đại diện của họ, tôi bắt đầu mặc những bộ quần áo như thế này để cho họ thấy rằng họ có thể mặc bất cứ thứ gì họ muốn để thể hiện sự độc đáo của mình."
L8_1.m_Talk_VTN = L9_1
L9_1 = "而我作为学生会长必需包容学生的不同个性，要以身作则做好表率，才开始这样穿的。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Deshalb habe ich als ihre Vertreterin angefangen, besonders auffällige Kleidung zu tragen – um zu zeigen, dass sie tragen können, was sie wollen, um ihre Einzigartigkeit zum Ausdruck zu bringen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Donc, en tant que représentante des élèves, j'ai commencé à porter des vêtements comme ceux-ci pour leur montrer qu'ils peuvent mettre ce qu'ils veulent et ainsi exprimer leur individualité."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
