L12_1 = "SCHOOL_PART1_NODE1_PROLOGUE@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 1700001
L11_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_LAUGH"
L11_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = 30
L11_1.m_Crash = L12_1
L12_1 = "오오! 그런 깊은 뜻이! 역시 사부!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "おぉ！　そんな深い意味が！　さすが師匠！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Oooo! So thoughtful! Master, you're the best!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "噢噢！真是深奧！不愧是師父！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "โออออ! รอบคอบจังค่ะอาจารย์! คุณเยี่ยมที่สุดเลย!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ồ! Thật là chu đáo! Sếp, cô là nhất!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "噢噢！不愧是师傅！真是良苦用心！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Oh! Wie aufmerksam! Meisterin, du bist klasse!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ooh ! Comme c'est attentionné ! Maître, vous êtes la meilleure !"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SCHOOL_PART1_NODE1_PROLOGUE@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1700001
L12_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L12_1.m_Pos = "L"
L12_1.m_Crash = 40
L13_1 = "음! 덕분에 본관 역시 수업 중에도 전투력을 유지하고 있다!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "うむ！　おかげで本官も授業中ですら戦闘力を維持している！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Mm, thanks to you, I'm able to maintain my combat power even during class."
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯！得益於此，本官在上課時也會保持戰鬥力的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อืม เพราะคุณเลยนะ ฉันเลยรักษาพังการต่อสู้ไว้ได้แม้แต่ตอนเรียน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Mm, nhờ có cô, tôi có thể duy trì sức mạnh chiến đấu của mình ngay cả trong lớp học."
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯！得益于此本官在上课时也会保持战斗力！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dank dir kann ich meine Kampfkraft sogar während des Unterrichts aufrechterhalten."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Hmm, grâce à vous je peux maintenir ma puissance au combat même pendant les cours."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 1700001
L13_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L13_1.m_bWaitClick = false
L13_1.m_fWaitTime = 0
