L14_1 = {}
L15_1 = "SCHOOL_PART1_NODE1_PROLOGUE@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 1700001
L14_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "그건 그렇고, 용무가 있어서 날 찾아왔다고 하지 않았던가요?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ところで、用があって私を訪ねてきたのではないのですか？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "By the way, didn't you say you wanted to talk to me about something?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "好了，你們來找我不是有事嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ว่าแต่ คุณว่ามีอะไรจะคุยกับฉันรึเปล่านะคะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nhân tiện, không phải cô nói rằng cô muốn nói chuyện riêng với tôi sao?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "好了，你们来找我不是有事吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Übrigens, sagtest du nicht, du wolltest etwas mit mir besprechen?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Mais au fait, vous n'aviez pas dit que vous vouliez me parler de quelque chose ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SCHOOL_PART1_NODE1_PROLOGUE@115#Talk"
