L17_1 = "SCHOOL_PART1_NODE1_PROLOGUE@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 1700001
L16_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_IDLE"
L16_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "사부도 요즘 도시에서 동물들이 실종되고 있다는 소문 들으셨어요?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "師匠、最近いろんなところで動物たちが行方不明になっている噂は聞きましたか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Master, have you heard that animals have been going missing from the city?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "師父也聽說了最近城市裡的動物不斷失蹤的消息吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อาจารย์คะ ได้ยินเรื่องสัตว์หายตัวไปจากเมืองบ้างมั้ยคะ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Sếp, cô có nghe về chuyện động vật bị mất tích ở thành phố không?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "师傅也听说了最近城市里的动物频繁失踪的消息吧？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Meisterin, hast du schon gehört, dass Tiere aus der Stadt verschwunden sind?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Maître, êtes-vous au courant que des animaux sont portés disparus en ville ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SCHOOL_PART1_NODE1_PROLOGUE@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 1700001
L17_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "네, 학생회도 그 사건에 대해선 예의주시 중입니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "はい、生徒会もその事件を注視しています。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Yes. The Student Council has been following the news."
L17_1.m_Talk_ENG = L18_1
L18_1 = "是的，學生會也在關注這件事情。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ค่ะ สภานักเรียนกำลังติดตามข่าวกันอยู่"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ừ. Hội Đồng Học Sinh vẫn theo dõi tin tức mà."
L17_1.m_Talk_VTN = L18_1
L18_1 = "没错，学生会也在关注这件事情。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ja. Das Schülerparlament hat die Nachrichten verfolgt."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oui. Le conseil des élèves a suivi cette affaire."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "SCHOOL_PART1_NODE1_PROLOGUE@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 1700001
L18_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "아끼는 애완동물이 사라진 학생들도 적지 않거든요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "大切なペットがいなくなってしまった生徒も少なくないんです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Quite a few students of ours have lost their pet animals."
L18_1.m_Talk_ENG = L19_1
L19_1 = "不少學生的寵物也失蹤了。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "มีสัตว์เลี้ยงของนักเรียนเราบางคนหายไปด้วยค่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Khá nhiều học sinh của chúng tôi đã mất những con vật cưng của họ. "
L18_1.m_Talk_VTN = L19_1
L19_1 = "不少学生的宠物也失踪了。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Einige unserer Schüler haben selbst Haustiere verloren."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Quelques-uns de nos propres élèves ont perdu un animal de compagnie."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "SCHOOL_PART1_NODE1_PROLOGUE@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 1700001
L19_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_LAUGH"
L19_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "앗! 그럼 저희랑 같이 동물들을 찾는 걸 도와주시는 건가요?!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "あっ！　じゃあ、僕たちと一緒に動物を探してくれるんですか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Ooh, then could you help us find the animals?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "啊！那麼可以幫我們一起找回動物嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "โห งั้นคุณช่วยเราตามหาสัตว์พวกนั้นได้มั้ยคะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ồ, vậy cô có thể giúp chúng tôi tìm những con vật đó không? "
L19_1.m_Talk_VTN = L20_1
L20_1 = "啊！那么可以帮我们一起找回动物吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Oh, könntest du uns dann helfen, die Tiere zu finden?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ooh, dans ce cas pourriez-vous nous aider à les retrouver ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "SCHOOL_PART1_NODE1_PROLOGUE@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 1700001
L20_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_DESPAIR"
L21_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "물론 교내 동아리의 활동을 돕는 것 또한 학생회의 역할이긴 합니다만......"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "もちろん、校内サークル活動を手伝うことも生徒会の役目なのですが……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "It's the Student Council's duty to assist student clubs in their activities,"
L20_1.m_Talk_ENG = L21_1
L21_1 = "雖說支援校內社團的活動，也是學生會的職責……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เป็นหน้าที่สภานักเรียนที่ต้องช่วยเหลือกิจกรรมของชมรมนักเรียนอยู่แล้วค่ะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nhiệm vụ của Hội Đồng Học Sinh là hỗ trợ các câu lạc bộ học sinh trong các hoạt động của họ, "
L20_1.m_Talk_VTN = L21_1
L21_1 = "虽说帮助校内社团的活动也是学生会的职责……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Es ist die Aufgabe des Schülerparlaments, die Schüler-AGs bei ihren Aktivitäten zu unterstützen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Il est du devoir du conseil des élèves d'aider les clubs d'étudiants dans leurs activités,"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "SCHOOL_PART1_NODE1_PROLOGUE@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 1700001
L21_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "학생회 임원들은 각자 맡은 역할로 바빠서 지원이 어려울 수도 있습니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "生徒会役員たちはそれぞれの役目を果たすために\n忙しいので、支援が難しいかもしれません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "but I don't know if its members have time to support you at this moment."
L21_1.m_Talk_ENG = L22_1
L22_1 = "但因為學生會的幹部都有各自要做的事情，所以支援可能會有困難。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่ฉันไม่รู้ว่าตอนนี้สมาชิกสภานักเรียนจะมีเวลามาช่วยสนับสนุนคุณกันรึเปล่านะคะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "nhưng tôi không biết liệu các thành viên có thời gian để hỗ trợ cô vào lúc này không. "
L21_1.m_Talk_VTN = L22_1
L22_1 = "但学生会的高级职员都有各自要做的事情，可能无法支援。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Allerdings weiß ich nicht, ob Parlamentarier gerade Zeit dafür haben …"
L21_1.m_Talk_DEU = L22_1
L22_1 = "mais je ne sais pas si des membres du conseil auront du temps à vous consacrer en ce moment."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "SCHOOL_PART1_NODE1_PROLOGUE@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 1700001
L22_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
