L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_SURPRISE"
L22_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = 30
L22_1.m_Crash = L23_1
L23_1 = "아앗, 아쉽다!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ううっ、残念！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Ack, that's a bummer."
L22_1.m_Talk_ENG = L23_1
L23_1 = "啊，好可惜喔！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ง่ะ น่าเศร้าจัง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ặc, thật là không đúng lúc mà."
L22_1.m_Talk_VTN = L23_1
L23_1 = "啊，好可惜！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ach, wie schade."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Argh, c'est dommage."
