L24_1 = "SCHOOL_PART1_NODE1_PROLOGUE@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 1700001
L23_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_LAUGH"
L24_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "하지만 걱정 말아요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ですが、ご心配なく。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But worry not."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但不用擔心。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่ไม่ต้องกังวลค่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nhưng đừng lo."
L23_1.m_Talk_VTN = L24_1
L24_1 = "但不用担心。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Aber keine Bange."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mais ne vous inquiétez pas."
L23_1.m_Talk_FRA = L24_1
