L25_1 = "SCHOOL_PART1_NODE1_PROLOGUE@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 1700001
L24_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "모든 임원들이 나서지 못할 뿐, 도움이 필요한 학생들을 그냥 돌려보내진 않을 겁니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "全役員が支援することが無理なだけで、\n助けが必要な生徒たちをそのまま帰らせたりなどはしません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I was speaking on behalf of the Council. You need help, and I'm not going to let you leave without it."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我們只是無法讓所有幹部都參與其中，但不會讓需要幫助的學生空手而歸的。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันกำลังพูดในนามของสภา คุณต้องการความช่วยเหลือ ฉันต้องไม่ปล่อยให้คุณกลับไปมือเปล่าอยู่แล้วค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi là người phát biểu của Hội Đồng mà. Nếu cô cần giúp đỡ, tôi sẽ không để cô rời đi mà không được gì. "
L24_1.m_Talk_VTN = L25_1
L25_1 = "只是不能让所有高级职员都参与，不会让需要帮助的学生无功而返的。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Im Namen des Parlaments sage ich: Ihr braucht Hilfe, und ich werde sie euch gewähren."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je parlais au nom du conseil. Vous avez besoin d'aide, et je ne vous laisserai pas repartir sans en recevoir."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SCHOOL_PART1_NODE1_PROLOGUE@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 1700001
L25_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_LAUGH"
L26_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "저라도 괜찮다면 여러분에게 도움을 드리기로 하죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "私でよろしければ、皆さんに協力します。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I'll help you. If you want me, of course."
L25_1.m_Talk_ENG = L26_1
L26_1 = "如果你們不介意，我很願意幫助大家。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันจะช่วยพวกคุณค่ะ ถ้าพวกคุณต้องการฉัน อย่างแน่นอน"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi sẽ giúp cô. Nếu cô muốn, dĩ nhiên rồi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "如果不介意，我愿意帮助大家。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich werde euch helfen. Wenn ihr wollt, natürlich."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je vous aiderai, si vous êtes d'accord bien entendu."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
