L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "이 일에 어울리는 한가한 적임자가 한 명 더 있어요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "この仕事にぴったりの、暇をしている適任者がもう一人います。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I know someone else who'd love to help you."
L29_1.m_Talk_ENG = L30_1
L30_1 = "還有一個人非常適合做這件事。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันรู้จักคนที่น่าจะอยากช่วยพวกคุณด้วยค่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi biết có người cũng muốn giúp cô."
L29_1.m_Talk_VTN = L30_1
L30_1 = "还有一个人非常适合做这件事。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich kenne noch jemanden, der gerne helfen würde."
L29_1.m_Talk_DEU = L30_1
