L37_1 = "SCHOOL_PART1_NODE1_PROLOGUE@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 1700001
L36_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "이디스는 학교의 방어시설과 전산시스템 관리를 책임지고 있어요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "イーディスは学校の防御施設と\nコンピューターシステム管理を担当しています。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Edith is in charge of the Academy's defense and computer systems."
L36_1.m_Talk_ENG = L37_1
L37_1 = "伊蒂絲負責管理學校的防禦設施和電算系統。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "อีดิธมีหน้าที่ดูแลการป้องกันและระบบคอมพิวเตอร์ของโรงเรียนค่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Edith phụ trách hệ thống máy tính và phòng thủ của Học Viện."
L36_1.m_Talk_VTN = L37_1
L37_1 = "伊迪丝负责管理学校的防御设施和电算系统。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Edith ist für die Verteidigungs- und Computersysteme der Akademie zuständig."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Edith est responsable de la défense et des systèmes informatiques de l'Académie."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SCHOOL_PART1_NODE1_PROLOGUE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 1700001
L37_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "L"
L38_1 = "사실상 일거리가 가장 많이 쏟아지는 직책 중 하나라고 할 수 있죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "事実上、一番仕事が多い役員の一人と言えます。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "She's one of the busiest people in school."
L37_1.m_Talk_ENG = L38_1
L38_1 = "事實上，這可以說是工作最繁重的職責之一。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เธอเป็นหนึ่งในคนที่ยุ่งที่สุดของโรงเรียนเรา"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cô ấy là một trong những người bận rộn nhất ở trường."
L37_1.m_Talk_VTN = L38_1
L38_1 = "可以说是任务最繁重的职责之一。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sie ist eine der geschäftigsten Personen der Schule."
L37_1.m_Talk_DEU = L38_1
L38_1 = "C'est l'une des personnes les plus occupées de l'école."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SCHOOL_PART1_NODE1_PROLOGUE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 1700001
L38_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L38_1.m_Pos = "R"
L38_1.m_Crash = 25
L39_1 = "네? 하지만 그냥 주무시고 계신데요?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ええ？　でも、ただ寝てるだけのようですけど……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Really? But she's asleep."
L38_1.m_Talk_ENG = L39_1
L39_1 = "是嗎？但她只是在睡覺耶？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จริงเหรอคะ? แต่เธอหลับอยู่นะคะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Thật sao? Nhưng cô ấy hay ngủ gật lắm."
L38_1.m_Talk_VTN = L39_1
L39_1 = "是吗？但她好像在睡觉呀？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wirklich? Aber sie schläft doch."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vraiment ? Mais elle est en train de dormir."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SCHOOL_PART1_NODE1_PROLOGUE@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 1700001
L39_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_LAUGH"
L40_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "대부분의 업무는 이디스가 만든 인공지능이 대신 수행해 주고 있거든요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "イーディスの作った人工知能がほとんどの業務を代わりに遂行してるのです。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Her AI is doing most of her work."
L39_1.m_Talk_ENG = L40_1
L40_1 = "大部分的工作會由伊蒂絲製作的人工智慧代為處理。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เอไอของเธอทำงานส่วนใหญ่ให้น่ะค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "AI của cô ấy đảm nhiệm hầu hết công việc của cô ấy."
L39_1.m_Talk_VTN = L40_1
L40_1 = "大部分工作会由伊迪丝制作的人工智能代替处理。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ihre KI erledigt den Großteil ihrer Arbeit."
L39_1.m_Talk_DEU = L40_1
L40_1 = "C'est son IA qui fait la majeure partie du travail."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "SCHOOL_PART1_NODE1_PROLOGUE@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 1700001
L40_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "L"
L41_1 = "얼핏 게을러 보일 수도 있지만, 실은 자기 역량으로 맡은 일을 훌륭히 해내고 있는 셈이죠."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "一見すると怠けてるように見えるかもしれませんが、\n実際は自分の力で担当業務を見事にこなしているわけです。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "She may appear lazy because she's not doing anything, but it's her brain that matters."
L40_1.m_Talk_ENG = L41_1
L41_1 = "雖然看上去在偷懶，但她是用自己的力量，出色地完成了份內的工作。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เธออาจดูเหมือนขี้เกียจเพราะไม่ทำอะไร แต่สมองของเธอต่างหากค่ะที่สำคัญ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cô ấy có vẻ lười biếng vì cô ấy không làm gì cả, nhưng bộ não của cô ấy mới là tuyệt vời."
L40_1.m_Talk_VTN = L41_1
L41_1 = "虽然感觉比较懒散，但是她是用自己的能力出色地完成了她的工作。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Sie mag faul erscheinen, weil sie nichts tut – aber es ist ihr Hirn, das zählt."
L40_1.m_Talk_DEU = L41_1
L41_1 = "On pourrait croire qu'elle est fainéante étant donné qu'elle ne fait rien, mais c'est son cerveau qui est important."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
