L43_1 = "SCHOOL_PART1_NODE1_PROLOGUE@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 1700001
L42_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_SERIOUS"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = 30
L42_1.m_Crash = L43_1
L43_1 = "눈을 감고도 모두 해치울 수 있다니! 그야말로 고수의 경지! 멋지다!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "目をつぶっても全部できるとは！　まさに達人の境地！\n素晴らしい！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So, she can do things with her eyes closed! Not everyone can reach that state. Awesome!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "閉著眼睛還能處理所有工作！簡直就是高手的境界！太帥了！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ก็คือเธอทำอะไรๆ ได้ทั้งที่หลับตาเหรอ! ไม่ใช่ทุกคนจะไปถึงขั้นนั้นได้นะ สุดยอด!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Vậy là cô ấy có thể làm việc ngay cả khi nhắm mắt sao! Không phải ai cũng có thể đạt được trạng thái đó. Tuyệt vời!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "闭着眼睛处理所有工作！简直就是高手的境界！太帅了！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Sie kann Dinge mit geschlossenen Augen tun! Nicht jeder kann einen solchen Zustand erreichen. Fantastisch!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "En résumé, elle peut accomplir des choses les yeux fermés ! Ce n'est pas donné à tout le monde. Incroyable !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCHOOL_PART1_NODE1_PROLOGUE@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 1700001
L43_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_DESPAIR"
L44_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "하지만 타의 모범이 되어야 할 학생회 임원이 한나절을 수면으로만 보내는 건 무척 비생산적이죠."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "しかし、皆さんの模範になるべき生徒会役員が\n半日寝てるだけとは、とても非生産的ですね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Nevertheless, as a member of the Council, who should be setting an example for other students, she shouldn't spend all day sleeping."
L43_1.m_Talk_ENG = L44_1
L44_1 = "但必須成為他人榜樣的學生會幹部，整天卻只知道睡覺，這樣恐怕會有反效果。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "กระนั้น ในฐานะของสมาชิกสภา ผู้ควรเป็นตัวอย่างให้นักเรียนคนอื่น เธอก็ไม่ควรนอนทั้งวันอยู่ดีค่ะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tuy nhiên, là một thành viên của Hội Đồng, tức là phải làm gương cho các học sinh khác, cô ấy không nên dành cả ngày để ngủ. "
L43_1.m_Talk_VTN = L44_1
L44_1 = "但应成为他人榜样的学生会高级职员整天只知道睡觉，确实不大合适。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Trotzdem sollte sie als Mitglied des Parlaments ein Vorbild für andere Schüler darstellen, und nicht den ganzen Tag mit Schlafen verbringen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Néanmoins, en tant que membre du conseil, qui devrait donner l'exemple aux autres étudiants, elle ne devrait pas passer ses journées à dormir."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SCHOOL_PART1_NODE1_PROLOGUE@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 1700001
L44_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_IDLE"
L45_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "학생회장으로서 그냥 두고 볼 수는 없어요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "生徒会長として見過ごすわけにはいきません。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "As the Student President, I can't let her do that, either."
L44_1.m_Talk_ENG = L45_1
L45_1 = "作為學生會長，我不能這樣坐視不管。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "และในฐานะประธานนักเรียน ฉันก็ปล่อยให้เธอทำแบบนั้นไม่ได้ด้วย"
L44_1.m_Talk_THA = L45_1
L45_1 = "Là Chủ Tịch Học Sinh, tôi cũng không thể để cô ấy như vậy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我作为学生会长不能坐视不管。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Als Schülerpräsidentin kann ich ihr das nicht gestatten."
L44_1.m_Talk_DEU = L45_1
L45_1 = "En tant que présidente du conseil, je ne peux pas non plus la laisser faire."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SCHOOL_PART1_NODE1_PROLOGUE@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
