L47_1.m_CharStrID = L48_1
L48_1 = "C_D"
L47_1.m_Pos = L48_1
L48_1 = "식별되지 않은 위험개체의 접근을 감지. 자동 방어 시스템을 전개합니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "識別されていない危険個体の接近を感知。\n自動防御システムを展開します。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Unidentified threat detected. Initializing auto-defense system..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "偵測到未識別的危險個體靠近，啟動自動防禦系統。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ตรวจพบภัยคุกคามที่ไม่อาจระบุได้ ระบบป้องกันตัวเองอัตโนมัติกำลังเริ่มทำงาน..."
L47_1.m_Talk_THA = L48_1
L48_1 = "Phát hiện mối đe dọa không xác định. Đang khởi động hệ thống phòng thủ tự động..."
L47_1.m_Talk_VTN = L48_1
L48_1 = "检测到未识别的危险个体靠近，启动自动防御系统。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Nicht identifizierte Bedrohung erkannt. Selbstverteidigungssystem wird initiiert …"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Détection de menace non identifiée. Initialisation du système d'autodéfense..."
L47_1.m_Talk_FRA = L48_1
