L50_1.m_Crash = 20
L51_1 = "왓! 신기해! 의자가 말을 하잖아?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "うわっ！　すごい！　椅子がしゃべってる！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Holy cow! Her chair can talk!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "哇！好神奇喔！椅子會說話耶？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อุตะ! เก้าอี้เธอพูดได้ด้วย!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúa ơi! Ghế của cô ấy có thể nói chuyện! "
L50_1.m_Talk_VTN = L51_1
L51_1 = "哇！好神奇！椅子会说话耶？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Heiliger Bimbam, ihr Stuhl kann sprechen!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "La vache ! Son fauteuil peut parler !"
L50_1.m_Talk_FRA = L51_1
