L1_1.m_Crash = L2_1
L2_1 = "그, 그게 중요한 게 아니라 미사일이 나오는 것 같은데요?!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そ、それより、ミサイルが飛んできてますよ！？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I-it can do more than that—it's producing a missile!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那、那個不是重點，它好像要發射導彈了？！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "มะ-มันทำได้มากกว่านั้นอีกนะ มันกำลังผลิตมิสไซล์ล่ะ!"
L1_1.m_Talk_THA = L2_1
L2_1 = "N-nó còn có thể làm nhiều điều hơn thế-nó có thể phóng ra tên lửa!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "那，那个不是重点，好像是要发射导弹了？！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Er kann noch viel mehr – er produziert eine Rakete!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "I-Il peut même faire plus que ça, il est en train d'armer un missile !"
L1_1.m_Talk_FRA = L2_1
