L9_1.m_Pos = "R"
L9_1.m_Crash = 20
L10_1 = "오오, 검으로 미사일을 전부 베어내다니! 굉장하다......"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "おお、剣でミサイルを全部切っちゃうとは！　素晴らしい……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Whoa, you cut down all the missiles with your sword! Super!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "喔喔，竟然用一把劍就把導彈全部斬斷了！好厲害……"
