L17_1 = "好像是伊蒂絲製作的自動反擊系統啟動錯誤了。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ระบบป้องกันอัตโนมัติของอีดิธต้องทำงานผิดพลาดแน่ๆ เลยค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Hệ thống phòng thủ tự động của Edith chắc bị lỗi rồi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "好像是伊迪丝制作的自动反击系统出错了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ediths Selbstverteidigungssystem muss eine Fehlfunktion gehabt haben."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Le système d'autodéfense d'Edith a probablement mal fonctionné."
L16_1.m_Talk_FRA = L17_1
