L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "아무래도, 인공지능이 저런 독특한 생명체에 대한 정보는 학습한 적이 없어서 벌어진 문제 같네요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "どうやら、人工知能があんなに独特な生命体の情報を\n学習しておらず生じた問題のようですね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The AI must not have seen such a unique life form before."
L17_1.m_Talk_ENG = L18_1
L18_1 = "看來是人工智慧沒有學習到這種獨特生命體的資訊，所以才會發生這樣的問題。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เอไอคงไม่เคยเห็นรูปแบบสิ่งมีชีวิตที่พิเศษแบบนี้มาก่อน"
L17_1.m_Talk_THA = L18_1
L18_1 = "AI chắc chưa nhìn thấy dạng sống độc đáo như vậy trước đây."
L17_1.m_Talk_VTN = L18_1
L18_1 = "应该是人工智能不了解这种独特生命体的信息，所以才会这样。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Die KI hat wohl noch nie eine so einzigartige Lebensform gesehen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "L'IA n'avait peut-être jamais vu une forme de vie aussi unique auparavant."
L17_1.m_Talk_FRA = L18_1
