L25_1.m_fTalkTime = 0.03
L26_1 = "まだ足りないじゃん……\n1日の目安量未満だよぅ……はああ……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "That's not enough. I need more sleep than that to function normally... *Yawn*"
L25_1.m_Talk_ENG = L26_1
L26_1 = "這不是還不夠嗎……還沒有達到每日推薦的睡眠量……哈啊……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "นั่นไม่พอนะ ฉันต้องนอนมากกว่านี้ถึงจะทำงานเป็นปกติ... *ฮ้าว*"
L25_1.m_Talk_THA = L26_1
L26_1 = "Như vậy là chưa đủ. Tôi cần ngủ nhiều hơn thế để hoạt động bình thường...* Ngáp* "
L25_1.m_Talk_VTN = L26_1
L26_1 = "还不够呢……还没达到每日推荐睡眠量……哈……"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Das reicht nicht. Ich brauche mehr Schlaf, um klarzukommen … *Gähn*"
L25_1.m_Talk_DEU = L26_1
L26_1 = "C'est pas suffisant. J'ai besoin de plus de sommeil que ça pour attaquer la journée... *Bâillement*"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
