L29_1 = "SCHOOL_PART1_NODE1_PROLOGUE@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 1700001
L28_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "L"
L29_1 = "이디스, 낮잠은 미뤄두고 도와줘야 할 일이 생겼어요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "イーディス、昼寝の前に手伝ってほしいことがあります。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Edith, you can sleep more later. For now, I need your help."
L28_1.m_Talk_ENG = L29_1
L29_1 = "伊蒂絲，先別睡了，有事情需要妳幫忙。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อีดิธ เธอค่อยนอนต่อทีหลังก็ได้ ตอนนี้ฉันต้องการความช่วยเหลือ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Edith, cô có thể ngủ thêm sau. Hiện tại, tôi cần sự giúp đỡ của cô. "
L28_1.m_Talk_VTN = L29_1
L29_1 = "伊迪丝，先别睡了，我有事情需要你帮忙。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Edith, du kannst später weiterschlafen. Aber jetzt brauche ich deine Hilfe."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Tu dormiras plus tard, Edith. J'ai besoin de ton aide, et tout de suite."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SCHOOL_PART1_NODE1_PROLOGUE@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1700001
L29_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "CHAIR_SCHOOL_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L29_1.m_Crash = 20
L30_1 = "으으, 조금만 더 있다가......"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "うう、もうちょっと……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Aww, not now..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "嗯嗯，我再睡一會兒……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อ๋อย ไม่เอาอะ..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Ặc, không phải vậy chứ..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "嗯嗯，我再睡一小会儿……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Och, nicht jetzt …"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oh nan, pas maintenant..."
L29_1.m_Talk_FRA = L30_1
