L32_1 = "SCHOOL_PART1_NODE1_PROLOGUE@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 1700001
L31_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SURPRISE"
L31_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Crash = 25
L32_1 = "아앗! 저 인형은 강습! 브레멘 동물전대의 잠꾸러기 펭귄, 안드레아스 소령!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ああっ！　あの人形は、[強襲！ブレーメン動物戦隊]の\n寝坊ペンギン、アンドレアス少佐！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Gosh, that's Major Andreas, the sleepy penguin character from \"Charge! Town Soldiers of Bremen!\""
L31_1.m_Talk_ENG = L32_1
L32_1 = "啊啊！那個玩偶是強襲！布萊梅動物戰隊的瞌睡蟲企鵝，安德列斯少校！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอ้โห นั่นสารวัตรแอนเดรส ตัวละครเพนกวินขี้เซาจาก \"บุกเลย! เหล่าทหารแห่งเมืองเบรเมน!\" นี่นา"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chúa ơi, đó là Thiếu Tá Andreas, nhân vật chim cánh cụt buồn ngủ trong \"Charge! Town Soldiers of Bremen!\""
L31_1.m_Talk_VTN = L32_1
L32_1 = "啊啊！那个娃娃是《强袭！不来梅动物战队》的瞌睡虫企鹅，安德烈斯少校！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Donnerwetter, das ist Major Andreas, der verschlafene Pinguin aus „Angriff! Stadtsoldaten von Bremen“."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oh là là, mais c'est le major Andreas, le pingouin paresseux de « Chargez, soldats de la ville de Brême ! »"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "SCHOOL_PART1_NODE1_PROLOGUE@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 1700001
L32_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "그것도 한정판으로 나왔던 반실물 사이즈!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "しかも、限定品として出た実物の半分サイズ！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "And it's even the limited-edition half life-size model!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "而且還是半實體大小的限定版耶！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แถมเป็นรุ่นลิมิเต็ดขนาดครึ่งนึงของคนจริงด้วย!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Và nó thậm chí còn là mô hình nửa vòng đời phiên bản giới hạn! "
L32_1.m_Talk_VTN = L33_1
L33_1 = "而且还是半实体大小的限定款！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Und es ist sogar die limitierte Auflage des Modells, in halber Lebensgröße!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Et en plus, c'est l'édition limitée de taille réduite !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
