L37_1 = "SCHOOL_PART1_NODE1_PROLOGUE@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 1700001
L36_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_LAUGH"
L37_1 = "CHAIR_SCHOOL_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "R_M_I"
L36_1.m_Pos = L37_1
L37_1 = "오오, 브레멘 동물전대 아시는구나?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "おぉ、ブレーメン動物戦隊を知ってるんですねぇ？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Oh, do you know Town Soldiers of Bremen?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "噢噢，妳也知道布萊梅動物戰隊？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "โอ๊ะ เธอรู้จักเหล่าทหารแห่งเมืองเบรเมนด้วยเหรอ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ồ, cô có biết Town Soldiers of Bremen không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "噢噢，你也知道不来梅动物战队？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ach, du kennst „Stadtsoldaten von Bremen“?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Oh, tu connais les Soldats de la ville de Brême ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SCHOOL_PART1_NODE1_PROLOGUE@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 1700001
L37_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_PRIDE"
L37_1.m_Face = L38_1
L37_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L37_1.m_Pos = "L"
L38_1 = "물론이다. 본관은 주말 저녁마다 본방을 꼬박꼬박 챙겨보고 있지."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "もちろんだ。本官は毎週末の夜に放送を欠かさずに見ている。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Absolutely. I never miss it each weekend."
L37_1.m_Talk_ENG = L38_1
L38_1 = "當然，本官每週末晚上都會看，一集都沒錯過。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แน่นอน ไม่เคยพลาดเลยทุกสุดสัปดาห์"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chắc chắn. Tôi chưa bao giờ bỏ lỡ nó mỗi cuối tuần."
L37_1.m_Talk_VTN = L38_1
L38_1 = "当然，本官每个周末晚上都会看，一集没落。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Klar doch! Ich lasse mir am Wochenende keine Folge entgehen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Carrément. Je regarde tous les week-ends."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SCHOOL_PART1_NODE1_PROLOGUE@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 1700001
L38_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L38_1.m_Pos = "L"
L39_1 = "지난 주에 개봉한 극장판은 첫날 영화관에서 세 번 감상하고 DVD특전도 구매했다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "先週公開した劇場版は公開初日に\n映画館で3回鑑賞して、特典付きDVDも購入した。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I even watched the movie version three times when it was first released, and I also bought the special DVD."
L38_1.m_Talk_ENG = L39_1
L39_1 = "上週上映的劇場版，我第一天就在電影院看了三次，還買了DVD特典。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ตอนเวอร์ชันหนังออกครั้งแรกฉันดูไปสามรอบ แถมยังซื้อดีวีดีพิเศษด้วย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi thậm chí đã xem phiên bản điện ảnh ba lần khi nó được phát hành lần đầu tiên và tôi cũng đã mua cả đĩa DVD đặc biệt nữa.  "
L38_1.m_Talk_VTN = L39_1
L39_1 = "上周上映的剧场版，我第一天就看了三次，还买了DVD特典。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich habe mir die Kinofassung dreimal angeschaut, als sie rauskam – und ich habe die Spezial-DVD gekauft."
L38_1.m_Talk_DEU = L39_1
L39_1 = "J'ai même vu le film trois fois quand il est sorti au cinéma, et j'ai acheté l'édition spéciale en DVD."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SCHOOL_PART1_NODE1_PROLOGUE@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 1700001
L39_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "UNIT_PRIDE"
L39_1.m_Face = L40_1
L40_1 = "CHAIR_SCHOOL_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "음! 안드레아스 소령이 주역으로 등장하는 영화 <color=#ffd34c>펭귄 이륙하다</color>는 시리즈들 사이에서도 명작 중의 명작이지!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "うん！　アンドレアス少佐が主人公として登場する\n映画<color=#ffd34c>ペンギン、離陸する</color>は、シリーズの中でもトップの名作だね！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Ah, <color=#ffd34c>The Penguin Flies</color> featuring Major Andreas as the main character is one of the best in the series."
L39_1.m_Talk_ENG = L40_1
L40_1 = "嗯！安德列斯少校以主角身份登場的電影<color=#ffd34c>企鵝起飛</color>，在系列中是神作中的神作！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อ๊ะ <color=#ffd34c>ไฟล์เพนกวิน</color>ที่มีสารวัตรแอนเดรสเป็นตัวละครหลักเป็นหนึ่งในตอนที่ดีที่สุดของซีรีส์เลย"
L39_1.m_Talk_THA = L40_1
L40_1 = "A, bộ <color=#ffd34c>The Penguin Flies</color> với nhân vật chính là Thiếu Tá Andreas là một trong những tập hay nhất trong sê-ri."
L39_1.m_Talk_VTN = L40_1
L40_1 = "嗯！安德烈斯少校以主角身份登场的电影<color=#ffd34c>企鹅起飞</color>确实是神作中的神作！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ah, <color=#ffd34c>„Der Pinguin fliegt“</color> mit Major Andreas als Hauptfigur ist eine der besten Folgen der Serie."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ah, <color=#ffd34c>L'envol du pingouin</color>, avec le major Andreas en personnage principal, c'est un des meilleurs épisodes de la série."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "SCHOOL_PART1_NODE1_PROLOGUE@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 1700001
L40_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_SERIOUS"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L40_1.m_Pos = "L"
L40_1.m_Crash = 40
L41_1 = "그 의견엔 전적으로 동의하는 바이다!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "その意見にはまったくもって同感だ！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I couldn't agree more."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我完全同意這個看法！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เห็นด้วยสุดๆ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi cực kỳ đồng ý."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我非常同意！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das finde ich auch!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Je suis complètement d'accord."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "SCHOOL_PART1_NODE1_PROLOGUE@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 1700001
L41_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "언제나 동네북 취급을 당하던 안드레아스가 소대를 위해 각성해 멋지게 활약을 펼치는 모습은 정말 감동 그 자체였어!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "いつもいじめられてたアンドレアスが、小隊のために覚醒して\nカッコよく活躍する姿は本当に感動した！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Andreas, instead of being the usual laughingstock of the bunch, awakens to his power and fights for his friends. I love it."
L41_1.m_Talk_ENG = L42_1
L42_1 = "受氣包安德列斯為了小隊，覺醒後大放異彩的模樣真的超感動！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แทนที่แอนเดรสจะเป็นตัวตลกของกลุ่มเหมือนทุกครั้ง กลายเป็นว่าพลังที่แท้จริงตื่นขึ้นแล้วต่อสู้เพื่อเพื่อนของเขา ฉันชอบมาก"
L41_1.m_Talk_THA = L42_1
L42_1 = "Andreas, thay vì trở thành trò cười thông thường của đám bạn, đã thức tỉnh sức mạnh của mình và chiến đấu vì bạn bè. Tôi thích điều đó. "
L41_1.m_Talk_VTN = L42_1
L42_1 = "受气包安德烈斯为了小队觉醒后大放异彩的样子真的超感动！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Andreas ist nicht die übliche Lachnummer des Haufens, sondern erweckt seine Kräfte und kämpft für seine Freunde. Super!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Au lieu d'être le ressort comique comme d'habitude, Andreas éveille ses pouvoirs et combat pour ses amis. Je suis fan."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "SCHOOL_PART1_NODE1_PROLOGUE@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 1700001
L42_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_LAUGH"
L43_1 = "CHAIR_SCHOOL_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "R"
L43_1 = "헤헤~ 너 작품 보는 법을 좀 아는구나?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "へえ～。君、見る目があるねぇ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Teehee! So, you've got an eye for anime, huh?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "嘿嘿～妳眼光不錯嘛？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฮิฮิ! งั้นเธอก็ชอบดูอนิเมะเหมือนกันสินะ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Hihi! Vậy là cô cũng thích anime sao?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "嘿嘿~你眼光不错嘛？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hihi … Du hast also eine Vorliebe für Anime, was?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Hi hi ! Tu es aussi amatrice d'animes, alors ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SCHOOL_PART1_NODE1_PROLOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 1700001
L43_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_PRIDE"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L43_1.m_Pos = "L"
L44_1 = "훗, 본관도 간만에 마음이 동하는 동지를 만난 것 같아서 무척 기쁘다!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ふっ、本官も久々に意見が合う仲間に会えてとても嬉しい！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Heh heh, I'm glad to have met a kindred spirit after so long."
L43_1.m_Talk_ENG = L44_1
L44_1 = "哼，能遇到志同道合的夥伴，本官也很高興！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แหะแหะ ฉันดีใจนะที่ในที่สุดก็เจอคนชอบเหมือนกันซะที"
L43_1.m_Talk_THA = L44_1
L44_1 = "He he, tôi rất mừng vì rất lâu rồi mới được gặp một tâm hồn đồng điệu."
L43_1.m_Talk_VTN = L44_1
L44_1 = "呼，能遇到志同道合的伙伴，本官也很高兴！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich bin froh, dass ich nach so langer Zeit eine Gleichgesinnte getroffen habe."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Eh ouais. Quel plaisir de pouvoir enfin partager ça avec quelqu'un."
L43_1.m_Talk_FRA = L44_1
