L47_1 = "SCHOOL_PART1_NODE1_PROLOGUE@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 1700001
L46_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_LAUGH"
L46_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L46_1.m_Pos = "L"
L46_1.m_Crash = 20
L47_1 = "와아, 두 사람 벌써 엄청 친해진 것 같아요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "わあ、二人とも既にとっても仲良しみたいですね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Wow, you guys sound like you're friends already."
L46_1.m_Talk_ENG = L47_1
L47_1 = "哇，你們兩個人已經打成一片了耶。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โอ้โห สองคนนี้เหมือนเป็นเพื่อนกันแล้วเลยอะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Wow, hai người trông như kiểu đã là bạn bè vậy."
L46_1.m_Talk_VTN = L47_1
L47_1 = "哇，你们两个人看起来很合得来。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Wow, ihr klingt, als wärt ihr bereits befreundet."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Eh ben, on dirait que vous êtes déjà meilleures amies."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "SCHOOL_PART1_NODE1_PROLOGUE@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 1700001
L47_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L47_1.m_Pos = "R"
L48_1 = 30
L47_1.m_Crash = L48_1
L48_1 = "덕심일체! 같은 취향으로 한 마음이 되면 의형제만큼이나 강한 유대로 이어지게 되지!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "オタク仲間！　同じ好みで気が合うと、\n義兄弟同然の強い絆で結ばれるのよ！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Anime fans forever! Nothing binds people together like sharing interests."
L47_1.m_Talk_ENG = L48_1
L48_1 = "趣味相投！擁有共同的興趣，可以形成堪比手足的關係！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แฟนอนิเมะฟอร์เอฟเวอร์! ไม่มีอะไรผูกพันคนเราเข้าด้วยกันได้เท่าความสนใจที่เหมือนกันอีกแล้ว"
L47_1.m_Talk_THA = L48_1
L48_1 = "Fan anime muôn năm! Chả có gì gắn kết mọi người bền chặt bằng chia sẻ sở thích với nhau."
L47_1.m_Talk_VTN = L48_1
L48_1 = "趣味相投！拥有共同的兴趣可以形成堪比手足的关系！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Anime-Fans auf ewig! Nichts verbindet Menschen so sehr wie gemeinsame Interessen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Évidemment, entre fans d'anime ! Rien de tel qu'un intérêt commun pour rapprocher les gens."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
