L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 1700001
L50_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_LAUGH"
L51_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "후훗, 아무래도 이디스에게 억지로 일을 시킬 필요는 없을 것 같군요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ふふっ、どうやらイーディスにむりやり仕事を\nやらせる必要はないみたいですね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Hah hah. It seems I won't have to force Edith to join us."
L50_1.m_Talk_ENG = L51_1
L51_1 = "呵呵，看來這次不用強迫伊蒂絲做事情了。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฮ่าฮ่า เหมือนฉันจะไม่ต้องบังคับให้อีดิธมาร่วมกับเราแล้วนะคะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ha ha. Dường như tôi sẽ không phải ép buộc Edith tham gia cùng chúng ta rồi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "呼呼，看来这次不用强迫伊迪丝干活了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Haha … Dann muss ich Edith wohl nicht zwingen, sich uns anzuschließen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ha ha. Je crois qu'il ne sera pas difficile de convaincre Edith de se joindre à nous."
L50_1.m_Talk_FRA = L51_1
