L2_1 = "CHAIR_SCHOOL_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "R"
L2_1 = "좋아, 내 도움이 필요하다고 했었지? 말해 봐~"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "よし、私の助けが必要だと言ってたよねぇ？　言ってごら～ん？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Alright, you said you needed my help. Tell me."
L1_1.m_Talk_ENG = L2_1
L2_1 = "好吧，你們需要我做什麼？說吧～"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เอาล่ะ เธอว่าเธออยากให้ฉันช่วยนี่ บอกมาสิ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Được rồi, cô đã nói rằng cần tôi giúp đỡ. Hãy cho tôi biết nào."
L1_1.m_Talk_VTN = L2_1
L2_1 = "好吧，你们需要我做什么？说吧~"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Okay, meine Hilfe wird benötigt? Worum gehts?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Bon, tu disais que tu avais besoin de moi. J'écoute."
L1_1.m_Talk_FRA = L2_1
