L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "정말 귀여운 털뭉치로군요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "本当に可愛いワンコですね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "What a cute furball!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "好可愛的小毛團唷。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เป็นเจ้าก้อนขนที่น่ารักอะไรอย่างนี้!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Thật là một cục bông đáng yêu!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "好可爱的小毛团。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Was für ein süßes Fellknäuel!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Quel adorable petite boule de poils !"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "SCHOOL_PART1_NODE1_PROLOGUE@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 1700001
L5_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_DESPAIR"
L6_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "이런 아이들을 납치하는 자들이 있다니, 천인공노할 일입니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "こんなに可愛い動物をさらう者たちがいるなんて、到底許せませんね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I can't believe some people took away these cute little things from their owners."
L5_1.m_Talk_ENG = L6_1
L6_1 = "竟然會有人綁架這麼可愛的小傢伙，簡直是人神共憤。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่อยากเชื่อเลยนะคะว่ามีคนพรากเจ้าตัวน้อยน่ารักแบบนี้ไปจากเจ้าของได้ลงคอ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi không thể tin được lại có người đã lấy đi những thứ nhỏ bé dễ thương này khỏi chủ nhân của chúng. "
L5_1.m_Talk_VTN = L6_1
L6_1 = "竟然有人绑架这么可爱的小家伙们，简直人神公愤。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich kann nicht fassen, dass es Menschen gibt, die diese niedlichen kleinen Kerle ihren Besitzern wegnehmen …"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je n'arrive pas à croire que des gens ont arraché ces mignonnes petites choses à leurs maîtres."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SCHOOL_PART1_NODE1_PROLOGUE@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 1700001
L6_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_PRIDE"
L6_1.m_Face = L7_1
L7_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "학생회의 이름을 걸고 반드시 동물친구들을 되찾아 드리도록 하죠."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "生徒会の名にかけて、必ず動物たちを助けてさしあげましょう。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I swear on the honor of the Student Council that I'll help you find them at all costs."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我以學生會的名義保證，一定會幫你們找回小動物。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันสาบานด้วยเกียรติของสภานักเรียนเลยค่ะว่าฉันต้องหาให้เจอให้ได้"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi xin thề với danh dự của Hội Đồng Học Sinh rằng tôi sẽ giúp cô tìm thấy chúng bằng mọi giá.  "
L6_1.m_Talk_VTN = L7_1
L7_1 = "我以学生会的名义保证，一定会帮你们找回小动物。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich schwöre bei der Ehre des Schülerparlaments, dass ich helfen werde, sie zu finden – koste es, was es wolle."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Sur l'honneur du conseil des élèves, je jure de t'aider à les retrouver, quoi qu'il en coûte."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SCHOOL_PART1_NODE1_PROLOGUE@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 1700001
L7_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L7_1.m_bWaitClick = true
