L11_1 = "SCHOOL_PART1_NODE1_PROLOGUE@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 1700001
L10_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_LAUGH"
L11_1 = "CHAIR_SCHOOL_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "R"
L11_1 = "실종된 동물을 구하러 간다니 굉장해~ <color=#ffd34c>폭시 일병 구하기</color>의 한 장면 같잖아~"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "行方不明になった動物を助けに行くなんて、すご～い。\n<color=#ffd34c>プライベート・フォクシー</color>の一幕みた～い。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "This is awesome, going on a mission to find missing animals. It's just like <color=#ffd34c>Saving Private Foxy</color>!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "竟然要去解救失蹤的動物，太刺激了～根本就是<color=#ffd34c>拯救大兵狐狸</color>的那個場景嘛～"
L10_1.m_Talk_TWN = L11_1
L11_1 = "สุดยอดเลย ออกปฏิบัติกภารกิจตามหาสัตว์ที่หายไป นี่มันเหมือน<color=#ffd34c>เซฟวิ่ง ไพรเวท ฟ็อกซี่ ฝ่าสมรภูมิน่ารัก</color>เลยนะ!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Điều này thật tuyệt vời, cô đang thực hiện một nhiệm vụ tìm kiếm những con vật bị mất tích. Nó giống như <color=#ffd34c>Saving Private Foxy</color> vậy!  "
L10_1.m_Talk_VTN = L11_1
L11_1 = "解救失踪的动物，太刺激了~就像<color=#ffd34c>拯救大兵狐狸</color>的一个场面~"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Großartig! Eine Mission, um vermisste Tiere zu finden – genau wie in <color=#ffd34c>Der Soldat James Fuchsi</color>!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Trop génial, on part en mission pour trouver des animaux disparus. Comme dans <color=#ffd34c>Il faut sauver le soldat Foxy</color> !"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SCHOOL_PART1_NODE1_PROLOGUE@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 1700001
L11_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_SERIOUS"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L11_1.m_Pos = "L"
L12_1 = "진정하도록! 이것은 놀이가 아니라 실전이다!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "落ち着け！　これは遊びではなく実戦だ！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Calm yourself. This is not a game—it's a real situation!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "冷靜點！這不是遊戲，而是實戰！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ใจเย็นนะ นี่ไม่ใช่เกม มันเป็นสถานการณ์จริง!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Bình tĩnh nào. Đây không phải là trò chơi-nó là một tình huống thực sự!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "别激动！这是实战，不是玩游戏！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Komm mal wieder runter – das hier ist kein Spiel, sondern eine echte Situation!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Calme-toi un peu. C'est pas un jeu, là, c'est la réalité !"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SCHOOL_PART1_NODE1_PROLOGUE@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1700001
L12_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "SORIM_REBBIT_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "지금쯤 알렉산더는 포로수용소에 갇힌 채 두려움에 떨고 있을 거야."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "今頃、アレクサンダーは捕虜収容所に閉じ込められて\n恐怖に震えているだろう。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Alexander could be locked up in a POW camp, trembling with fear right now."
L12_1.m_Talk_ENG = L13_1
L13_1 = "可憐的亞歷山大現在應該被關在俘虜營裡，瑟瑟發抖著。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อเล็กซานเดอร์อาจถูกขังอยู่ในค่ายเชลยสัตว์ และกำลังตัวสั่นด้วยความหวาดกลัว"
L12_1.m_Talk_THA = L13_1
L13_1 = "Alexander có thể đã bị nhốt ở trại POW và đang rất sợ hãi."
L12_1.m_Talk_VTN = L13_1
L13_1 = "可怜的亚历山大现在应该被关在俘虏营里。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Alexander ist vielleicht gerade in einem Kriegsgefangenenlager eingesperrt und zittert vor Angst."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Si ça se trouve, Alexander est dans un camp de prisonniers, à trembler de peur."
L12_1.m_Talk_FRA = L13_1
