L16_1 = "SCHOOL_PART1_NODE1_PROLOGUE@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 1700001
L15_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L15_1.m_Pos = "R"
L16_1 = "야채 가게 할아버지 말로는 빵 봉투를 뒤집어 쓴 이상한 손님들이 알렉산더를 데려갔대."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "八百屋のおじいさんの話によると、紙袋をかぶった\n変なお客さんたちがアレクサンダーを連れていったらしいよ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "The greengrocer said some strange customers with bread bags over their heads took Alexander."
L15_1.m_Talk_ENG = L16_1
L16_1 = "蔬菜店的爺爺說，是一群頭上套著麵包袋的怪異客人帶走了亞歷山大。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "คนขายผักผลไม้บอกว่ามีลูกค้าแปลกๆ ที่สวมถุงกระดาษปิดบังใบหน้าจับตัวอเล็กซานเดอร์ไปล่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Anh bán rau cho biết một số khách hàng lạ mặt với túi bánh mì để trên đầu đã bắt Alexander.  "
L15_1.m_Talk_VTN = L16_1
L16_1 = "蔬菜店的爷爷说，是一群头上套着面包袋的客人们带走了亚历山大。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Der Gemüsehändler sagte, dass ein paar seltsame Kunden mit Brottüten über dem Kopf Alexander mitgenommen haben."
L15_1.m_Talk_DEU = L16_1
L16_1 = "D'après le marchand, des clients étranges avec des sacs à pain sur la tête ont enlevé Alexander."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SCHOOL_PART1_NODE1_PROLOGUE@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 1700001
L16_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "HARIM_REBBIT_NULL_NULL"
L16_1.m_Pos = "L"
L17_1 = "빵 봉투요......?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "紙袋ですか……？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Bread bags?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "麵包袋……？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถุงกระดาษเหรอ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Túi bánh mì?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "面包袋……？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Brottüten?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Des sacs à pain ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SCHOOL_PART1_NODE1_PROLOGUE@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 1700001
L17_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "HOJIN_REBBIT_NULL_NULL"
L17_1.m_Pos = "R"
L18_1 = "응. 할아버지가 알아차리고 쫓아갔는데 버려진 놀이동산 근처에서 사라졌다나 봐."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "うん。おじいさんが気づいて追いかけたけど、\n遊園地の廃墟周辺で消えたらしいよ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Yes. When he realized they took his dog, he followed them. They disappeared near the abandoned theme park."
L17_1.m_Talk_ENG = L18_1
L18_1 = "嗯，爺爺發現後馬上追了上去，但他們在廢棄的遊樂場附近就不見了。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ใช่ พอเขารู้ตัวว่าพวกนั้นจับหมาของเขาไป เขาก็รีบตาม พวกนั้นหายตัวไปแถวสวนสนุกร้าง"
L17_1.m_Talk_THA = L18_1
L18_1 = "Đúng vậy. Khi nhận ra họ dắt theo con chó của mình, anh ta đã đi theo họ. Họ biến mất gần công viên giải trí bỏ hoang. "
L17_1.m_Talk_VTN = L18_1
L18_1 = "嗯，爷爷发现后马上去追了，可惜在废弃的游乐场附近不见了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ja. Als er merkte, dass sie seinen Hund mitnahmen, folgte er ihnen. Sie verschwanden in der Nähe des verlassenen Freizeitparks."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oui. Quand il a compris qu'ils avaient pris son chien, il les a suivis. Ils ont disparu près du parc d'attractions abandonné."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
