L20_1 = "SCHOOL_PART1_NODE1_PROLOGUE@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 1700001
