L20_1 = "PRESIDENT_SCHOOL_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "그럼 그 놀이동산부터 조사해 봐야겠네요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "では、その遊園地から調べてみましょう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Then, we'd better check that theme park first."
L19_1.m_Talk_ENG = L20_1
L20_1 = "那就從那個遊樂場開始調查吧。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "งั้น เราก็ควรไปตรวจสอบสวนสนุกนั่นกันก่อนเลยค่ะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Vậy thì chúng ta nên kiểm tra công viên giải trí đó trước. "
L19_1.m_Talk_VTN = L20_1
L20_1 = "那就从那个游乐场开始调查吧。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Dann sollten wir uns zuerst den Freizeitpark ansehen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Dans ce cas, allons d'abord chercher de ce côté-là."
L19_1.m_Talk_FRA = L20_1
