L23_1 = "SCHOOL_PART1_NODE1_PROLOGUE@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 1700001
L22_1.m_CutScenStrID = "SCHOOL_PART1_NODE1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "CHAIR_SCHOOL_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "R"
L23_1 = "단서를 찾으면 나한테 줘. 주르의 분석 시스템을 쓰면 알렉산더와 친구들이 어딨는지 알아낼 수 있을 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "手がかりが見つかったら私にちょうだい。\nJ.O.U.R.の分析システムを使えばアレクサンダーと友達の居場所がわかると思うよ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Let me know if you find any clues. I can use J.O.U.R.'s analysis system to locate Alexander and other animal pals."
L22_1.m_Talk_ENG = L23_1
L23_1 = "找到線索後就告訴我。只要使用朱爾的分析系統，應該就可以掌握亞歷山大和動物朋友們的位置。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ถ้าเจอเบาะแสอะไรก็บอกฉันนะ ฉันใช้ระบบวิเคราะห์ของ J.O.U.R. หาตำแหน่งของอเล็กซานเดอร์กับเพื่อนๆ สัตว์ได้"
L22_1.m_Talk_THA = L23_1
L23_1 = " Hãy cho tôi biết nếu cô tìm thấy bất kỳ manh mối nào. Tôi có thể sử dụng hệ thống phân tích của J.O.U.R. để xác định vị trí của Alexander và những động vật khác. "
L22_1.m_Talk_VTN = L23_1
L23_1 = "找到线索后告诉我，使用朱尔的分析系统应该就可以找出亚历山大和动物朋友的位置。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Gebt mir Bescheid, wenn ihr Hinweise findet. Ich kann das Analysesystem von J.O.U.R. nutzen, um Alexander und andere tierische Freunde zu finden."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Préviens-moi si tu trouves des indices. Je pourrai me servir du système d'analyse de J.O.U.R. pour retrouver Alexander et ses copains à pattes."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
