L24_1 = 30
L23_1.m_Crash = L24_1
L24_1 = "좋다! 애니멀 레스큐 스페셜포스, 통칭 A.R.S팀 출동!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "よし！\nアニマルレスキュースペシャルフォース、通称A.R.Sチーム出動！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Got it! Let's go, Animal Rescue Specialists, a.k.a. A.R.S.!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "好！動物救助特別搜查隊，A.R.S出動！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "รับทราบ! ไปกันเลย เหล่าผู้ชำนาญการด้านการช่วยเหลือสัตว์ (Animal Rescue Specialists a.k.a. ARS)!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Hiểu rồi! Đi thôi, Chuyên Gia Cứu Hộ Động Vật ARS! "
L23_1.m_Talk_VTN = L24_1
L24_1 = "好！动物特别搜查队，A.R.S出动！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Alles klar! Los gehts, Tierrettungsspezialisten, auch bekannt als TRS!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Pigé ! En avant, les Spécialistes du Sauvetage d'Animaux ! Les SSA !"
L23_1.m_Talk_FRA = L24_1
